package com.arber.pvmtools;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import net.runelite.client.ui.overlay.infobox.InfoBoxPriority;
import net.runelite.client.ui.overlay.infobox.Timer;

class CombatPotionTimerInfoBox extends Timer
{
	private static final Color WARNING_RED = new Color(255, 45, 45);

	private final CombatPotionTimerType type;
	private final PvmToolsPlugin plugin;
	private long sortValue;

	CombatPotionTimerInfoBox(CombatPotionTimerType type, Duration duration, BufferedImage image, PvmToolsPlugin plugin)
	{
		super(Math.max(1L, duration.toMillis()), ChronoUnit.MILLIS, image, plugin);
		this.type = type;
		this.plugin = plugin;
		setTooltip(type.getDisplayName());
		setPriority(InfoBoxPriority.HIGH);
	}

	CombatPotionTimerType getType()
	{
		return type;
	}

	long getSortValue()
	{
		return sortValue;
	}

	void setSortValue(long sortValue)
	{
		this.sortValue = sortValue;
	}

	Duration getRemainingDuration()
	{
		return Duration.between(Instant.now(), getEndTime());
	}

	boolean isInWarningWindow()
	{
		Duration remaining = getRemainingDuration();
		return !remaining.isNegative()
			&& !remaining.isZero()
			&& remaining.compareTo(Duration.ofSeconds(plugin.getWarningSeconds())) <= 0;
	}

	@Override
	public Color getTextColor()
	{
		return isInWarningWindow() ? WARNING_RED : Color.WHITE;
	}

	@Override
	public String getName()
	{
		return type.name();
	}
}

package com.arber.pvmtools;

import net.runelite.api.gameval.ItemID;

enum CombatPotionTimerType
{
	PRAYER("Prayer", net.runelite.api.ItemID.PRAYER_POTION4),
	OVERLOAD("Overload", ItemID.NZONE4DOSEOVERLOADPOTION),
	RAID_OVERLOAD("Overload", ItemID.RAIDS_VIAL_OVERLOAD_STRONG_4),
	BLIGHTED_OVERLOAD("Blighted overload", ItemID.DEADMAN4DOSEOVERLOAD),
	ANTIFIRE("Antifire", ItemID._4DOSE1ANTIDRAGON),
	EXTENDED_ANTIFIRE("Extended antifire", ItemID._4DOSE2ANTIDRAGON),
	SUPER_ANTIFIRE("Super antifire", ItemID._4DOSE3ANTIDRAGON),
	EXTENDED_SUPER_ANTIFIRE("Extended super antifire", ItemID._4DOSE4ANTIDRAGON),
	ANTI_VENOM_PLUS("Anti-venom+", ItemID.ANTIVENOM_4),
	DIVINE_SUPER_ATTACK("Divine super attack", ItemID._4DOSEDIVINEATTACK),
	DIVINE_SUPER_STRENGTH("Divine super strength", ItemID._4DOSEDIVINESTRENGTH),
	DIVINE_SUPER_DEFENCE("Divine super defence", ItemID._4DOSEDIVINEDEFENCE),
	DIVINE_SUPER_COMBAT("Divine super combat", ItemID._4DOSEDIVINECOMBAT),
	DIVINE_RANGING("Divine ranging", ItemID._4DOSEDIVINERANGE),
	DIVINE_MAGIC("Divine magic", ItemID._4DOSEDIVINEMAGIC),
	DIVINE_BASTION("Divine bastion", ItemID._4DOSEDIVINEBASTION),
	DIVINE_BATTLEMAGE("Divine battlemage", ItemID._4DOSEDIVINEBATTLEMAGE),
	;

	private final String displayName;
	private final int imageItemId;

	CombatPotionTimerType(String displayName, int imageItemId)
	{
		this.displayName = displayName;
		this.imageItemId = imageItemId;
	}

	String getDisplayName()
	{
		return displayName;
	}

	int getImageItemId()
	{
		return imageItemId;
	}
}

package com.arber.pvmtools;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class CombatPotionWarningOverlay extends Overlay
{
	private final Client client;
	private final PvmToolsPlugin plugin;

	@Inject
	private CombatPotionWarningOverlay(Client client, PvmToolsPlugin plugin)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		this.client = client;
		this.plugin = plugin;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Color color = plugin.getScreenFlashColor();
		if (color == null || color.getAlpha() <= 0)
		{
			return null;
		}

		Rectangle bounds = client.getCanvas().getBounds();
		if (bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}

		graphics.setColor(color);
		graphics.fillRect(0, 0, bounds.width, bounds.height);
		return null;
	}
}

package com.arber.pvmtools;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemLayer;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class GroundItemHighlightOverlay extends Overlay
{
	private static final int OUTLINE_FEATHER = 4;

	private final Client client;
	private final PvmToolsPlugin plugin;
	private final ModelOutlineRenderer modelOutlineRenderer;
	private final ConfigManager configManager;
	private final ItemManager itemManager;

	@Inject
	private GroundItemHighlightOverlay(
		Client client,
		PvmToolsPlugin plugin,
		ModelOutlineRenderer modelOutlineRenderer,
		ConfigManager configManager,
		ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.modelOutlineRenderer = modelOutlineRenderer;
		this.configManager = configManager;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldHighlightGroundItems())
		{
			return null;
		}

		Color color = plugin.getGroundItemHighlightColor();
		int width = plugin.getGroundItemHighlightWidth();
		GroundItemVisibilityFilter visibilityFilter = GroundItemVisibilityFilter.load(configManager, itemManager);
		List<Tile> groundItemTiles = plugin.getGroundItemTiles();
		for (Tile tile : groundItemTiles)
		{
			renderTile(tile, color, width, visibilityFilter);
		}

		return null;
	}

	private void renderTile(Tile tile, Color color, int width, GroundItemVisibilityFilter visibilityFilter)
	{
		if (tile == null || tile.getGroundItems() == null || tile.getGroundItems().isEmpty())
		{
			return;
		}

		ItemLayer itemLayer = tile.getItemLayer();
		if (itemLayer == null)
		{
			return;
		}

		for (TileItem item : tile.getGroundItems())
		{
			if (visibilityFilter.isVisible(item) && plugin.meetsGroundItemHighlightMinimum(item))
			{
				modelOutlineRenderer.drawOutline(itemLayer, item, width, color, OUTLINE_FEATHER);
			}
		}
	}
}

package com.arber.pvmtools;

public enum GroundItemLifetimeMode
{
	ALL_VISIBLE("All visible"),
	VALUE_THRESHOLD("Value threshold");

	private final String displayName;

	GroundItemLifetimeMode(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.arber.pvmtools;

import com.google.common.collect.Table;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemID;
import net.runelite.api.ItemLayer;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.grounditems.GroundItemsPlugin;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.QuantityFormatter;

class GroundItemLifetimeTextOverlay extends Overlay
{
	private static final String GROUND_ITEMS_GROUP = "grounditems";
	private static final int MAX_DISTANCE = 2500;
	private static final int OFFSET_Z = 20;
	private static final int STRING_GAP = 15;

	private final Client client;
	private final PvmToolsPlugin plugin;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final PluginManager pluginManager;
	private final TextComponent textComponent = new TextComponent();
	private final Map<WorldPoint, Integer> offsetMap = new HashMap<>();
	private final Map<ItemKey, ItemLifetime> itemLifetimes = new HashMap<>();
	private GroundItemsPlugin groundItemsPlugin;

	@Inject
	private GroundItemLifetimeTextOverlay(
		Client client,
		PvmToolsPlugin plugin,
		ConfigManager configManager,
		ItemManager itemManager,
		PluginManager pluginManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.pluginManager = pluginManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGHEST);
	}

	void onItemSpawned(Tile tile, TileItem item)
	{
		if (tile == null || item == null)
		{
			return;
		}

		int tick = client.getTickCount();
		int despawnTick = item.getDespawnTime();
		if (despawnTick <= tick)
		{
			return;
		}

		ItemKey key = new ItemKey(tile.getWorldLocation(), item.getId());
		itemLifetimes.computeIfAbsent(key, ignored -> new ItemLifetime(tick, despawnTick));
	}

	void onItemDespawned(Tile tile, TileItem item)
	{
		if (tile != null && item != null)
		{
			itemLifetimes.remove(new ItemKey(tile.getWorldLocation(), item.getId()));
		}
	}

	void reset()
	{
		itemLifetimes.clear();
		offsetMap.clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldShowGroundItemLifetimeText() || !isGroundItemTextVisible())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		GroundItemVisibilityFilter visibilityFilter = GroundItemVisibilityFilter.load(configManager, itemManager);
		Table groundItemsTable = getGroundItemsTable();
		offsetMap.clear();
		for (Tile tile : plugin.getGroundItemTiles())
		{
			renderTile(graphics, tile, player, visibilityFilter, groundItemsTable);
		}

		int tick = client.getTickCount();
		itemLifetimes.entrySet().removeIf(entry -> entry.getValue().despawnTick <= tick);
		return null;
	}

	@SuppressWarnings({"rawtypes", "unchecked"})
	private void renderTile(
		Graphics2D graphics,
		Tile tile,
		Player player,
		GroundItemVisibilityFilter visibilityFilter,
		Table groundItemsTable)
	{
		if (tile == null || tile.getGroundItems() == null || tile.getGroundItems().isEmpty())
		{
			return;
		}

		ItemLayer itemLayer = tile.getItemLayer();
		if (itemLayer == null)
		{
			return;
		}

		LocalPoint groundPoint = LocalPoint.fromWorld(itemLayer.getWorldView(), itemLayer.getWorldLocation());
		if (groundPoint == null || groundPoint.getWorldView() == net.runelite.api.WorldView.TOPLEVEL
			&& player.getLocalLocation().distanceTo(groundPoint) > MAX_DISTANCE)
		{
			return;
		}

		Map<Integer, TileItem> itemsById = new LinkedHashMap<>();
		for (TileItem item : tile.getGroundItems())
		{
			itemsById.put(item.getId(), item);
		}

		List<TileItem> orderedItems = new ArrayList<>(itemsById.size());
		if (groundItemsTable != null)
		{
			Map row = groundItemsTable.row(tile.getWorldLocation());
			for (Object itemId : row.keySet())
			{
				TileItem item = itemsById.remove(itemId);
				if (item != null)
				{
					orderedItems.add(item);
				}
			}
		}
		orderedItems.addAll(itemsById.values());

		for (TileItem item : orderedItems)
		{
			if (!visibilityFilter.isVisible(item)
				|| !shouldDisplayOwnership(item)
				|| !plugin.shouldShowGroundItemLifetime(item.getId(), item.getQuantity()))
			{
				continue;
			}

			ItemLifetime lifetime = getOrCreateLifetime(tile, item);
			if (lifetime == null)
			{
				continue;
			}

			String text = buildItemText(item);
			if (text == null)
			{
				continue;
			}
			Point textPoint = Perspective.getCanvasTextLocation(
				client,
				graphics,
				groundPoint,
				text,
				itemLayer.getHeight() + OFFSET_Z);
			if (textPoint == null)
			{
				continue;
			}

			int offset = offsetMap.compute(tile.getWorldLocation(), (key, value) -> value == null ? 0 : value + 1);
			renderLifetimeText(graphics, text, textPoint.getX(), textPoint.getY() - STRING_GAP * offset, lifetime);
		}
	}

	@SuppressWarnings("rawtypes")
	private Table getGroundItemsTable()
	{
		if (groundItemsPlugin == null)
		{
			for (Plugin candidate : pluginManager.getPlugins())
			{
				if (candidate instanceof GroundItemsPlugin)
				{
					groundItemsPlugin = (GroundItemsPlugin) candidate;
					break;
				}
			}
		}

		return groundItemsPlugin == null ? null : groundItemsPlugin.getCollectedGroundItems();
	}

	private ItemLifetime getOrCreateLifetime(Tile tile, TileItem item)
	{
		int tick = client.getTickCount();
		int despawnTick = item.getDespawnTime();
		if (despawnTick <= tick)
		{
			return null;
		}

		ItemKey key = new ItemKey(tile.getWorldLocation(), item.getId());
		return itemLifetimes.computeIfAbsent(key, ignored -> new ItemLifetime(tick, despawnTick));
	}

	private void renderLifetimeText(Graphics2D graphics, String text, int x, int y, ItemLifetime lifetime)
	{
		int tick = client.getTickCount();
		int totalTicks = Math.max(1, lifetime.despawnTick - lifetime.spawnTick);
		float remaining = Math.max(0f, Math.min(1f, (lifetime.despawnTick - tick) / (float) totalTicks));
		FontMetrics metrics = graphics.getFontMetrics();
		int fullWidth = metrics.stringWidth(text);
		int visibleWidth = Math.min(fullWidth, Math.max(1, Math.round(fullWidth * remaining)));
		boolean outline = getBooleanGroundItemConfig("textOutline", false);

		renderFadedText(graphics, text, x, y, outline);

		Shape oldClip = graphics.getClip();
		graphics.clipRect(x - 2, y - metrics.getAscent() - 2, visibleWidth + 2, metrics.getHeight() + 4);
		renderText(graphics, text, x, y, lifetimeColor(remaining), outline);
		graphics.setClip(oldClip);
	}

	private void renderFadedText(Graphics2D graphics, String text, int x, int y, boolean outline)
	{
		int darkness = plugin.getGroundItemLifetimeFadedTextDarkness();
		int channel = 255 - darkness * 255 / 100;
		renderText(graphics, text, x, y, new Color(channel, channel, channel), outline);
	}

	private void renderText(Graphics2D graphics, String text, int x, int y, Color color, boolean outline)
	{
		textComponent.setText(text);
		textComponent.setColor(color);
		textComponent.setOutline(outline);
		textComponent.setPosition(new java.awt.Point(x, y));
		textComponent.render(graphics);
	}

	private Color lifetimeColor(float remaining)
	{
		return Color.getHSBColor(remaining / 3f, 0.95f, 1f);
	}

	private String buildItemText(TileItem item)
	{
		ItemComposition composition;
		try
		{
			composition = itemManager.getItemComposition(item.getId());
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
		if (composition == null)
		{
			return null;
		}

		StringBuilder text = new StringBuilder(composition.getName());
		int quantity = item.getQuantity();
		if (quantity > 1)
		{
			text.append(" (").append(QuantityFormatter.quantityToStackSize(quantity)).append(')');
		}

		if (item.getId() != ItemID.COINS_995)
		{
			appendPrice(text, composition, quantity);
		}

		return text.toString();
	}

	private void appendPrice(StringBuilder text, ItemComposition composition, int quantity)
	{
		String mode = getGroundItemConfig("priceDisplayMode", "BOTH");
		if ("OFF".equalsIgnoreCase(mode))
		{
			return;
		}

		int realItemId = composition.getNote() != -1 ? composition.getLinkedNoteId() : composition.getId();
		long gePrice = (long) itemManager.getItemPrice(realItemId) * quantity;
		long haPrice = (long) composition.getHaPrice() * quantity;
		if ("BOTH".equalsIgnoreCase(mode))
		{
			appendPriceValue(text, "GE", gePrice);
			appendPriceValue(text, "HA", haPrice);
			return;
		}

		appendPriceValue(text, null, "HA".equalsIgnoreCase(mode) ? haPrice : gePrice);
	}

	private void appendPriceValue(StringBuilder text, String prefix, long price)
	{
		if (price <= 0)
		{
			return;
		}

		text.append(" (");
		if (prefix != null)
		{
			text.append(prefix).append(": ");
		}
		text.append(QuantityFormatter.quantityToStackSize(price)).append(" gp)");
	}

	private boolean isGroundItemTextVisible()
	{
		String mode = getGroundItemConfig("itemHighlightMode", "BOTH");
		return "BOTH".equalsIgnoreCase(mode) || "OVERLAY".equalsIgnoreCase(mode);
	}

	private boolean shouldDisplayOwnership(TileItem item)
	{
		String mode = getGroundItemConfig("ownershipFilterMode", "ALL");
		if ("DROPS".equalsIgnoreCase(mode))
		{
			return item.getOwnership() == TileItem.OWNERSHIP_SELF || item.getOwnership() == TileItem.OWNERSHIP_GROUP;
		}
		if ("TAKEABLE".equalsIgnoreCase(mode))
		{
			return item.getOwnership() != TileItem.OWNERSHIP_OTHER || client.getVarbitValue(VarbitID.IRONMAN) == 0;
		}
		return true;
	}

	private String getGroundItemConfig(String key, String defaultValue)
	{
		String value = configManager.getConfiguration(GROUND_ITEMS_GROUP, key);
		return value == null || value.isBlank() ? defaultValue : value;
	}

	private boolean getBooleanGroundItemConfig(String key, boolean defaultValue)
	{
		String value = configManager.getConfiguration(GROUND_ITEMS_GROUP, key);
		return value == null ? defaultValue : Boolean.parseBoolean(value);
	}

	private static final class ItemLifetime
	{
		private final int spawnTick;
		private final int despawnTick;

		private ItemLifetime(int spawnTick, int despawnTick)
		{
			this.spawnTick = spawnTick;
			this.despawnTick = despawnTick;
		}
	}

	private static final class ItemKey
	{
		private final WorldPoint worldPoint;
		private final int itemId;

		private ItemKey(WorldPoint worldPoint, int itemId)
		{
			this.worldPoint = worldPoint;
			this.itemId = itemId;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof ItemKey))
			{
				return false;
			}

			ItemKey that = (ItemKey) other;
			return itemId == that.itemId && worldPoint.equals(that.worldPoint);
		}

		@Override
		public int hashCode()
		{
			return 31 * worldPoint.hashCode() + itemId;
		}
	}
}

package com.arber.pvmtools;

import java.util.Collections;
import java.util.List;
import net.runelite.api.ItemComposition;
import net.runelite.api.TileItem;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

final class GroundItemVisibilityFilter
{
	private static final String GROUND_ITEMS_GROUP = "grounditems";
	private static final String HIDDEN_ITEMS_KEY = "hiddenItems";
	private static final String HIGHLIGHTED_ITEMS_KEY = "highlightedItems";
	private static final String SHOW_HIGHLIGHTED_ONLY_KEY = "showHighlightedOnly";
	private static final String HIDE_UNDER_VALUE_KEY = "hideUnderValue";
	private static final String DONT_HIDE_UNTRADEABLES_KEY = "dontHideUntradeables";
	private static final String DEFAULT_HIDDEN_ITEMS = "Vial, Ashes, Coins, Bones, Bucket, Jug, Seaweed";
	private static final int MATCH_NONE = 0;
	private static final int MATCH_WILDCARD = 1;
	private static final int MATCH_EXACT = 2;

	private final ItemManager itemManager;
	private final List<String> hiddenItems;
	private final List<String> highlightedItems;
	private final boolean showHighlightedOnly;
	private final int hideUnderValue;
	private final boolean dontHideUntradeables;

	static GroundItemVisibilityFilter load(ConfigManager configManager, ItemManager itemManager)
	{
		return new GroundItemVisibilityFilter(
			itemManager,
			getCsvConfig(configManager, HIDDEN_ITEMS_KEY, DEFAULT_HIDDEN_ITEMS),
			getCsvConfig(configManager, HIGHLIGHTED_ITEMS_KEY, ""),
			getBooleanConfig(configManager, SHOW_HIGHLIGHTED_ONLY_KEY, false),
			getIntConfig(configManager, HIDE_UNDER_VALUE_KEY, 0),
			getBooleanConfig(configManager, DONT_HIDE_UNTRADEABLES_KEY, true));
	}

	private GroundItemVisibilityFilter(
		ItemManager itemManager,
		List<String> hiddenItems,
		List<String> highlightedItems,
		boolean showHighlightedOnly,
		int hideUnderValue,
		boolean dontHideUntradeables)
	{
		this.itemManager = itemManager;
		this.hiddenItems = hiddenItems;
		this.highlightedItems = highlightedItems;
		this.showHighlightedOnly = showHighlightedOnly;
		this.hideUnderValue = hideUnderValue;
		this.dontHideUntradeables = dontHideUntradeables;
	}

	boolean isVisible(TileItem item)
	{
		ItemComposition composition;
		try
		{
			composition = itemManager.getItemComposition(item.getId());
		}
		catch (RuntimeException ignored)
		{
			// Keep RuneLite's own visible loot visible while item definitions are reloading.
			return true;
		}
		if (composition == null)
		{
			return true;
		}

		String name = composition.getName();
		int highlighted = matches(highlightedItems, name, item.getQuantity());
		int hidden = matches(hiddenItems, name, item.getQuantity());
		boolean isHighlighted = highlighted == MATCH_EXACT
			|| highlighted == MATCH_WILDCARD && hidden != MATCH_EXACT;
		boolean isHidden = hidden == MATCH_EXACT && highlighted != MATCH_EXACT
			|| hidden == MATCH_WILDCARD && highlighted == MATCH_NONE;

		if (isHidden || showHighlightedOnly && !isHighlighted)
		{
			return false;
		}

		return isHighlighted || !isHiddenByValue(item, composition);
	}

	private boolean isHiddenByValue(TileItem item, ItemComposition composition)
	{
		if (hideUnderValue <= 0)
		{
			return false;
		}

		int itemId = item.getId();
		int linkedItemId = composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
		long gePrice = linkedItemId == 995 ? 1L : itemManager.getItemPrice(linkedItemId);
		int haPrice = composition.getHaPrice();
		boolean canHideByValue = gePrice > 0 || composition.isGeTradeable() || !dontHideUntradeables;
		return canHideByValue && gePrice < hideUnderValue && haPrice < hideUnderValue;
	}

	private static List<String> getCsvConfig(ConfigManager configManager, String key, String defaultValue)
	{
		String value = configManager.getConfiguration(GROUND_ITEMS_GROUP, key);
		if (value == null)
		{
			value = defaultValue;
		}

		return value == null || value.trim().isEmpty() ? Collections.emptyList() : Text.fromCSV(value);
	}

	private static boolean getBooleanConfig(ConfigManager configManager, String key, boolean defaultValue)
	{
		String value = configManager.getConfiguration(GROUND_ITEMS_GROUP, key);
		return value == null ? defaultValue : Boolean.parseBoolean(value);
	}

	private static int getIntConfig(ConfigManager configManager, String key, int defaultValue)
	{
		String value = configManager.getConfiguration(GROUND_ITEMS_GROUP, key);
		if (value == null)
		{
			return defaultValue;
		}

		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException ignored)
		{
			return defaultValue;
		}
	}

	private static int matches(List<String> configuredItems, String itemName, int quantity)
	{
		int wildcardMatch = MATCH_NONE;
		for (String configuredItem : configuredItems)
		{
			ItemThreshold threshold = ItemThreshold.fromName(configuredItem);
			if (threshold == null || !threshold.quantityHolds(quantity))
			{
				continue;
			}

			if (threshold.wildcard)
			{
				if (WildcardMatcher.matches(threshold.name, itemName))
				{
					wildcardMatch = MATCH_WILDCARD;
				}
				continue;
			}

			if (threshold.name.equalsIgnoreCase(itemName))
			{
				return MATCH_EXACT;
			}
		}

		return wildcardMatch;
	}

	private static final class ItemThreshold
	{
		private final String name;
		private final int quantity;
		private final boolean lessThan;
		private final boolean wildcard;

		private ItemThreshold(String name, int quantity, boolean lessThan, boolean wildcard)
		{
			this.name = name;
			this.quantity = quantity;
			this.lessThan = lessThan;
			this.wildcard = wildcard;
		}

		private static ItemThreshold fromName(String name)
		{
			if (name == null || name.trim().isEmpty())
			{
				return null;
			}

			boolean wildcard = name.contains("*");
			boolean lessThan = false;
			int quantity = 0;
			int split = findQuantitySplit(name);
			if (split >= 0)
			{
				lessThan = name.charAt(split) == '<';
				try
				{
					quantity = Integer.parseInt(name.substring(split + 1).trim());
					name = name.substring(0, split);
				}
				catch (NumberFormatException ignored)
				{
					quantity = 0;
					lessThan = false;
				}
			}

			return new ItemThreshold(name.trim(), quantity, lessThan, wildcard);
		}

		private static int findQuantitySplit(String name)
		{
			for (int i = name.length() - 1; i >= 0; i--)
			{
				char c = name.charAt(i);
				if (Character.isDigit(c) || Character.isWhitespace(c))
				{
					continue;
				}

				return c == '<' || c == '>' ? i : -1;
			}

			return -1;
		}

		private boolean quantityHolds(int itemQuantity)
		{
			return lessThan ? itemQuantity < quantity : itemQuantity > quantity;
		}
	}
}

package com.arber.pvmtools;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxPriority;

class InventorySpacesInfoBox extends InfoBox
{
	private static final int IMAGE_SIZE = 32;
	private static final int IMAGE_PADDING = 2;
	private static final int LOW_SPACE_THRESHOLD = 3;
	private static final String FONT_NAME = "Arial";
	private static final Color WARNING_YELLOW = new Color(255, 218, 69);
	private static final Color WARNING_RED = new Color(255, 45, 45);

	private int freeSpaces;

	InventorySpacesInfoBox(int freeSpaces, Plugin plugin)
	{
		super(createSpacesImage(freeSpaces), plugin);
		this.freeSpaces = freeSpaces;
		setPriority(InfoBoxPriority.MED);
	}

	boolean setFreeSpaces(int freeSpaces)
	{
		if (this.freeSpaces == freeSpaces)
		{
			return false;
		}

		this.freeSpaces = freeSpaces;
		setImage(createSpacesImage(freeSpaces));
		return true;
	}

	int getFreeSpaces()
	{
		return freeSpaces;
	}

	@Override
	public String getText()
	{
		return "";
	}

	@Override
	public Color getTextColor()
	{
		return getSpacesColor(freeSpaces);
	}

	@Override
	public String getName()
	{
		return "INVENTORY_SPACES";
	}

	private static BufferedImage createSpacesImage(int freeSpaces)
	{
		BufferedImage image = new BufferedImage(IMAGE_SIZE, IMAGE_SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			String text = Integer.toString(freeSpaces);
			Font font = fitFont(graphics, text);
			graphics.setFont(font);

			FontMetrics metrics = graphics.getFontMetrics();
			int x = (IMAGE_SIZE - metrics.stringWidth(text)) / 2;
			int y = ((IMAGE_SIZE - metrics.getHeight()) / 2) + metrics.getAscent();

			graphics.setColor(Color.BLACK);
			for (int offsetX = -1; offsetX <= 1; offsetX++)
			{
				for (int offsetY = -1; offsetY <= 1; offsetY++)
				{
					if (offsetX != 0 || offsetY != 0)
					{
						graphics.drawString(text, x + offsetX, y + offsetY);
					}
				}
			}

			graphics.setColor(getSpacesColor(freeSpaces));
			graphics.drawString(text, x, y);
		}
		finally
		{
			graphics.dispose();
		}

		return image;
	}

	private static Font fitFont(Graphics2D graphics, String text)
	{
		for (int size = 30; size >= 14; size--)
		{
			Font font = new Font(FONT_NAME, Font.BOLD, size);
			FontMetrics metrics = graphics.getFontMetrics(font);
			if (metrics.stringWidth(text) <= IMAGE_SIZE - IMAGE_PADDING * 2
				&& metrics.getHeight() <= IMAGE_SIZE - IMAGE_PADDING * 2)
			{
				return font;
			}
		}

		return new Font(FONT_NAME, Font.BOLD, 14);
	}

	private static Color getSpacesColor(int freeSpaces)
	{
		if (freeSpaces <= 0)
		{
			return WARNING_RED;
		}

		if (freeSpaces <= LOW_SPACE_THRESHOLD)
		{
			return WARNING_YELLOW;
		}

		return Color.WHITE;
	}
}

