package com.arber.pvmtools;

/** Keeps a trailing refresh pending when several updates share one interval. */
final class PvmPanelRefreshCheckpoint
{
	private boolean pending;
	private long lastRefreshMillis = -1L;

	void request()
	{
		pending = true;
	}

	boolean takeIfDue(long nowMillis, long intervalMillis, boolean force)
	{
		if (!pending || (!force && lastRefreshMillis >= 0L && nowMillis >= lastRefreshMillis
			&& nowMillis - lastRefreshMillis < Math.max(0L, intervalMillis)))
		{
			return false;
		}
		pending = false;
		lastRefreshMillis = nowMillis;
		return true;
	}
}

package com.arber.pvmtools;

import java.util.EnumMap;
import java.util.EnumSet;

final class PvmStatsPersistenceCheckpoint
{
	private final EnumSet<PvmToolsStatsPeriod> dirtyPeriods = EnumSet.noneOf(PvmToolsStatsPeriod.class);
	private final EnumMap<PvmToolsStatsPeriod, Long> lastPersistMillis = new EnumMap<>(PvmToolsStatsPeriod.class);

	void markDirty(PvmToolsStatsPeriod period)
	{
		if (period != null)
		{
			dirtyPeriods.add(period);
		}
	}

	boolean isDirty(PvmToolsStatsPeriod period)
	{
		return dirtyPeriods.contains(period);
	}

	boolean isDue(PvmToolsStatsPeriod period, long nowMillis, long intervalMillis, boolean force)
	{
		if (!isDirty(period) || force)
		{
			return isDirty(period);
		}

		long lastMillis = lastPersistMillis.getOrDefault(period, 0L);
		long interval = Math.max(0L, intervalMillis);
		return nowMillis >= lastMillis && nowMillis - lastMillis >= interval;
	}

	void persisted(PvmToolsStatsPeriod period, long nowMillis)
	{
		if (period == null)
		{
			return;
		}

		dirtyPeriods.remove(period);
		lastPersistMillis.put(period, Math.max(0L, nowMillis));
	}
}

package com.arber.pvmtools;

import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

final class PvmSupplyIgnoreList
{
	private static final Pattern SEPARATOR = Pattern.compile("[,;\\r\\n]+");
	private static final Pattern DOSE_SUFFIX = Pattern.compile("\\s*\\(\\d+\\)\\s*$");
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");
	private static final PvmSupplyIgnoreList EMPTY = new PvmSupplyIgnoreList(Collections.emptySet());

	private final Set<String> itemNames;

	private PvmSupplyIgnoreList(Set<String> itemNames)
	{
		this.itemNames = itemNames;
	}

	static PvmSupplyIgnoreList empty()
	{
		return EMPTY;
	}

	static PvmSupplyIgnoreList fromConfig(String value)
	{
		if (value == null || value.isBlank())
		{
			return empty();
		}

		Set<String> names = new HashSet<>();
		for (String entry : SEPARATOR.split(value))
		{
			String normalized = normalize(entry);
			if (!normalized.isEmpty())
			{
				names.add(normalized);
			}
		}
		return names.isEmpty()
			? empty()
			: new PvmSupplyIgnoreList(Collections.unmodifiableSet(names));
	}

	boolean isEmpty()
	{
		return itemNames.isEmpty();
	}

	boolean matches(String itemName)
	{
		return itemNames.contains(normalize(itemName));
	}

	static String normalize(String itemName)
	{
		if (itemName == null)
		{
			return "";
		}

		String withoutDose = DOSE_SUFFIX.matcher(itemName).replaceFirst("");
		return WHITESPACE.matcher(withoutDose.trim())
			.replaceAll(" ")
			.toLowerCase(Locale.ENGLISH);
	}
}

