	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1,
		VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6
	};

	private static final Map<Integer, Integer> RUNE_POUCH_ITEMS = buildRunePouchItems();

	private final Client client;
	private final ItemManager itemManager;
	private final SupplyUsageConsumer usageConsumer;
	private final Map<Integer, Integer> inventoryRuneCounts = new HashMap<>();
	private final Map<Integer, Integer> pendingRuneUsage = new HashMap<>();
	private final int[] runePouchTypes = new int[RUNE_POUCH_TYPE_VARBITS.length];
	private final int[] previousRunePouchTypes = new int[RUNE_POUCH_TYPE_VARBITS.length];
	private final int[] runePouchQuantities = new int[RUNE_POUCH_QUANTITY_VARBITS.length];
	private final Map<Integer, BlowpipeDart> blowpipeDartsByProjectile = new HashMap<>();

	private boolean initialized;
	private boolean magicXpChangedThisTick;
	private Integer lastMagicExperience;
	private int lastCastActionTick = Integer.MIN_VALUE;
	private int weaponItemId = -1;
	private int weaponQuantity;
	private int ammoItemId = -1;
	private int ammoQuantity;
	private int capeItemId = -1;
	private int quiverAmmoItemId = -1;
	private int quiverAmmoQuantity;
	private BlowpipeDart blowpipeDart;
	private int lastBlowpipeShotTick = Integer.MIN_VALUE;
	private int lastPoweredStaffShotTick = Integer.MIN_VALUE;
	private double blowpipeDartUsageRemainder;
	private int blowpipeScaleUsageRemainder;

	PvmSupplyUsageTracker(Client client, ItemManager itemManager, SupplyUsageConsumer usageConsumer)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.usageConsumer = usageConsumer;
		registerBlowpipeDart(ItemID.BRONZE_DART, 226);
		registerBlowpipeDart(ItemID.IRON_DART, 227);
		registerBlowpipeDart(ItemID.STEEL_DART, 228);
		registerBlowpipeDart(ItemID.BLACK_DART, 32);
		registerBlowpipeDart(ItemID.MITHRIL_DART, 229);
		registerBlowpipeDart(ItemID.ADAMANT_DART, 230);
		registerBlowpipeDart(ItemID.RUNE_DART, 231);
		registerBlowpipeDart(ItemID.AMETHYST_DART, 1936);
		registerBlowpipeDart(ItemID.DRAGON_DART, 1122);
	}

	void initialize()
	{
		reset();
		syncInventoryBaseline(client.getItemContainer(InventoryID.INVENTORY));
		syncEquipmentBaseline(client.getItemContainer(InventoryID.EQUIPMENT));
		for (int index = 0; index < RUNE_POUCH_TYPE_VARBITS.length; index++)
		{
			runePouchTypes[index] = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[index]);
			previousRunePouchTypes[index] = runePouchTypes[index];
			runePouchQuantities[index] = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[index]);
		}
		quiverAmmoItemId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		quiverAmmoQuantity = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		int magicExperience = client.getSkillExperience(Skill.MAGIC);
		lastMagicExperience = magicExperience < 0 ? null : magicExperience;
		initialized = true;
	}

	void reset()
	{
		initialized = false;
		magicXpChangedThisTick = false;
		lastMagicExperience = null;
		lastCastActionTick = Integer.MIN_VALUE;
		inventoryRuneCounts.clear();
		pendingRuneUsage.clear();
		weaponItemId = -1;
		weaponQuantity = 0;
		ammoItemId = -1;
		ammoQuantity = 0;
		capeItemId = -1;
		quiverAmmoItemId = -1;
		quiverAmmoQuantity = 0;
		blowpipeDart = null;
		lastBlowpipeShotTick = Integer.MIN_VALUE;
		lastPoweredStaffShotTick = Integer.MIN_VALUE;
		blowpipeDartUsageRemainder = 0d;
		blowpipeScaleUsageRemainder = 0;
	}

	/**
	 * Rebase the Magic XP signal after RuneLite has finished loading the logged-in account.
	 * This prevents the first full-account StatChanged event from confirming inventory
	 * rune or blighted-sack changes that happened while the client was loading.
	 */
	void rebaseMagicXpBaseline()
	{
		int magicExperience = client.getSkillExperience(Skill.MAGIC);
		lastMagicExperience = magicExperience < 0 ? null : magicExperience;
		magicXpChangedThisTick = false;
	}

	void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = Text.removeTags(event.getMenuOption());
		if (option != null && option.toLowerCase(Locale.ENGLISH).startsWith("cast"))
		{
			lastCastActionTick = client.getTickCount();
		}
	}

	void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.MAGIC || event.getXp() < 0)
		{
			return;
		}
		int experience = event.getXp();
		if (lastMagicExperience == null)
		{
			lastMagicExperience = experience;
			return;
		}
		if (experience > lastMagicExperience)
		{
			magicXpChangedThisTick = true;
			lastMagicExperience = experience;
		}
	}

	void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!initialized)
		{
			initialize();
		}

		if (event.getContainerId() == InventoryID.INVENTORY.getId())
		{
			trackInventoryRunes(event.getItemContainer());
		}
		else if (event.getContainerId() == InventoryID.EQUIPMENT.getId())
		{
			trackEquipmentAmmo(event.getItemContainer());
		}
	}

	void onVarbitChanged(VarbitChanged event)
	{
		if (!initialized)
		{
			return;
		}

		for (int index = 0; index < RUNE_POUCH_TYPE_VARBITS.length; index++)
		{
			if (event.getVarbitId() == RUNE_POUCH_TYPE_VARBITS[index])
			{
				previousRunePouchTypes[index] = runePouchTypes[index];
				runePouchTypes[index] = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[index]);
				return;
			}

			if (event.getVarbitId() == RUNE_POUCH_QUANTITY_VARBITS[index])
			{
				int newQuantity = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[index]);
				int used = runePouchQuantities[index] - newQuantity;
				if (used > 0 && used < MAX_RUNE_USE_PER_CAST)
				{
					int runeType = runePouchTypes[index] > 0 ? runePouchTypes[index] : previousRunePouchTypes[index];
					Integer runeItemId = RUNE_POUCH_ITEMS.get(runeType);
					if (runeItemId != null)
					{
						pendingRuneUsage.merge(runeItemId, used, Integer::sum);
					}
				}
				runePouchQuantities[index] = newQuantity;
				return;
			}
		}

		if (event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO
			|| event.getVarpId() == VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT)
		{
			trackQuiverAmmo();
		}
	}

	void onProjectileMoved(ProjectileMoved event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || !isBlowpipe(weaponItemId) || !isBlowpipeAnimation(localPlayer.getAnimation()))
		{
			return;
		}

		Projectile projectile = event.getProjectile();
		BlowpipeDart detectedDart = blowpipeDartsByProjectile.get(projectile.getId());
		if (detectedDart != null)
		{
			blowpipeDart = detectedDart;
		}
	}

	void onGameTick()
	{
		if (!initialized)
		{
			initialize();
		}

		int tick = client.getTickCount();
		boolean castObserved = magicXpChangedThisTick
			|| tick - lastCastActionTick >= 0 && tick - lastCastActionTick <= CAST_ACTION_TICK_WINDOW;
		if (castObserved)
		{
			pendingRuneUsage.forEach((itemId, quantity) -> record(itemId, quantity, PvmToolsPlugin.SupplyCostType.RUNE));
		}
		pendingRuneUsage.clear();
		trackWeaponChargeUsage(tick);
		magicXpChangedThisTick = false;
	}

	private void trackInventoryRunes(ItemContainer itemContainer)
	{
		Map<Integer, Integer> newCounts = collectItems(itemContainer, this::isInventoryMagicSupply);
		inventoryRuneCounts.forEach((itemId, oldQuantity) ->
		{
			int used = oldQuantity - newCounts.getOrDefault(itemId, 0);
			if (used > 0 && used < MAX_RUNE_USE_PER_CAST)
			{
				pendingRuneUsage.merge(itemId, used, Integer::sum);
			}
		});
		inventoryRuneCounts.clear();
		inventoryRuneCounts.putAll(newCounts);
	}

	private void syncInventoryBaseline(ItemContainer itemContainer)
	{
		inventoryRuneCounts.clear();
		inventoryRuneCounts.putAll(collectItems(itemContainer, this::isInventoryMagicSupply));
	}

	private boolean isInventoryMagicSupply(int itemId)
	{
		switch (itemId)
		{
			case ItemID.BLIGHTED_ANCIENT_ICE_SACK:
			case ItemID.BLIGHTED_ENTANGLE_SACK:
			case ItemID.BLIGHTED_TELEPORT_SPELL_SACK:
			case ItemID.BLIGHTED_VENGEANCE_SACK:
			case ItemID.BLIGHTED_SURGE_SACK:
				return true;
			default:
				return RUNE_POUCH_ITEMS.containsValue(itemId);
		}
	}

	private Map<Integer, Integer> collectItems(ItemContainer itemContainer, IntPredicate filter)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (itemContainer == null)
		{
			return counts;
		}

		for (Item item : itemContainer.getItems())
		{
			if (item.getId() > 0 && filter.test(item.getId()))
			{
				counts.merge(item.getId(), Math.max(0, item.getQuantity()), Integer::sum);
			}
		}
		return counts;
	}

	private void trackEquipmentAmmo(ItemContainer equipment)
	{
		Item newWeapon = getEquipmentItem(equipment, EQUIPMENT_WEAPON_SLOT);
		Item newAmmo = getEquipmentItem(equipment, EQUIPMENT_AMMO_SLOT);
		Item newCape = getEquipmentItem(equipment, EQUIPMENT_CAPE_SLOT);
		trackEquipmentSlotUsage(weaponItemId, weaponQuantity, newWeapon, this::isThrownAmmo);
		trackEquipmentSlotUsage(ammoItemId, ammoQuantity, newAmmo, this::isRangedAmmo);
		weaponItemId = newWeapon.getId();
		weaponQuantity = Math.max(0, newWeapon.getQuantity());
		ammoItemId = newAmmo.getId();
		ammoQuantity = Math.max(0, newAmmo.getQuantity());
		capeItemId = newCape.getId();
	}

	private void syncEquipmentBaseline(ItemContainer equipment)
	{
		Item weapon = getEquipmentItem(equipment, EQUIPMENT_WEAPON_SLOT);
		Item ammo = getEquipmentItem(equipment, EQUIPMENT_AMMO_SLOT);
		Item cape = getEquipmentItem(equipment, EQUIPMENT_CAPE_SLOT);
		weaponItemId = weapon.getId();
		weaponQuantity = Math.max(0, weapon.getQuantity());
		ammoItemId = ammo.getId();
		ammoQuantity = Math.max(0, ammo.getQuantity());
		capeItemId = cape.getId();
	}

	private void trackEquipmentSlotUsage(int oldItemId, int oldQuantity, Item newItem, IntPredicate ammoFilter)
	{
		if (oldItemId <= 0 || oldQuantity <= 0 || !ammoFilter.test(oldItemId))
		{
			return;
		}

		int used = 0;
		if (newItem.getId() == oldItemId && newItem.getQuantity() < oldQuantity)
		{
			used = oldQuantity - Math.max(0, newItem.getQuantity());
		}
		else if (newItem.getId() <= 0 && oldQuantity <= 2 && client.getLocalPlayer() != null
			&& client.getLocalPlayer().getInteracting() != null)
		{
			used = oldQuantity;
		}

		if (used > 0 && used <= 2)
		{
			record(oldItemId, used, PvmToolsPlugin.SupplyCostType.AMMO);
		}
	}

	private void trackQuiverAmmo()
	{
		int newItemId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		int newQuantity = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		int used = 0;
		if (newItemId == quiverAmmoItemId && newQuantity < quiverAmmoQuantity)
		{
			used = quiverAmmoQuantity - Math.max(0, newQuantity);
		}
		else if (newItemId <= 0 && quiverAmmoItemId > 0 && quiverAmmoQuantity <= 2
			&& client.getLocalPlayer() != null && client.getLocalPlayer().getInteracting() != null)
		{
			used = quiverAmmoQuantity;
		}

		if (used > 0 && used <= 2 && isRangedAmmo(quiverAmmoItemId))
		{
			record(quiverAmmoItemId, used, PvmToolsPlugin.SupplyCostType.AMMO);
		}
		quiverAmmoItemId = newItemId;
		quiverAmmoQuantity = Math.max(0, newQuantity);
	}

	private void trackWeaponChargeUsage(int tick)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		int animation = localPlayer.getAnimation();
		if (isBlowpipe(weaponItemId) && isBlowpipeAnimation(animation)
			&& localPlayer.getAnimationFrame() == 0 && lastBlowpipeShotTick != tick)
		{
			lastBlowpipeShotTick = tick;
			recordBlowpipeShot();
			return;
		}

		if (localPlayer.getAnimationFrame() != 0 || lastPoweredStaffShotTick == tick)
		{
			return;
		}

		if (animation == POWERED_STAFF_ATTACK_ANIMATION && recordPoweredStaffRunes())
		{
			lastPoweredStaffShotTick = tick;
		}
		else if (animation == SHADOW_ATTACK_ANIMATION && isItem(weaponItemId, ItemID.TUMEKENS_SHADOW))
		{
			record(ItemID.CHAOS_RUNE, 2, PvmToolsPlugin.SupplyCostType.RUNE);
			record(ItemID.SOUL_RUNE, 5, PvmToolsPlugin.SupplyCostType.RUNE);
			lastPoweredStaffShotTick = tick;
		}
	}

	private boolean recordPoweredStaffRunes()
	{
		if (isAnyItem(weaponItemId, ItemID.TRIDENT_OF_THE_SWAMP, ItemID.TRIDENT_OF_THE_SWAMP_E,
			ItemID.TRIDENT_OF_THE_SWAMP_O, ItemID.TRIDENT_OF_THE_SWAMP_E_O))
		{
			recordTridentRunes();
			record(ItemID.ZULRAHS_SCALES, 1, PvmToolsPlugin.SupplyCostType.ZULRAH_SCALE);
			return true;
		}
		if (isAnyItem(weaponItemId, ItemID.TRIDENT_OF_THE_SEAS_FULL, ItemID.TRIDENT_OF_THE_SEAS,
			ItemID.TRIDENT_OF_THE_SEAS_E, ItemID.TRIDENT_OF_THE_SEAS_O,
			ItemID.TRIDENT_OF_THE_SEAS_FULL_O, ItemID.TRIDENT_OF_THE_SEAS_E_O))
		{
			recordTridentRunes();
			return true;
		}
		if (isItem(weaponItemId, ItemID.WARPED_SCEPTRE))
		{
			record(ItemID.CHAOS_RUNE, 2, PvmToolsPlugin.SupplyCostType.RUNE);
			record(ItemID.EARTH_RUNE, 5, PvmToolsPlugin.SupplyCostType.RUNE);
			return true;
		}
		if (isAnyItem(weaponItemId, ItemID.SANGUINESTI_STAFF, ItemID.HOLY_SANGUINESTI_STAFF))
		{
			record(ItemID.BLOOD_RUNE, 3, PvmToolsPlugin.SupplyCostType.RUNE);
			return true;
		}
		return false;
	}

	private void recordTridentRunes()
	{
		record(ItemID.CHAOS_RUNE, 1, PvmToolsPlugin.SupplyCostType.RUNE);
		record(ItemID.DEATH_RUNE, 1, PvmToolsPlugin.SupplyCostType.RUNE);
		record(ItemID.FIRE_RUNE, 5, PvmToolsPlugin.SupplyCostType.RUNE);
	}

	private void recordBlowpipeShot()
	{
		blowpipeScaleUsageRemainder += 2;
		int scalesUsed = blowpipeScaleUsageRemainder / 3;
		blowpipeScaleUsageRemainder %= 3;
		if (scalesUsed > 0)
		{
			record(ItemID.ZULRAHS_SCALES, scalesUsed, PvmToolsPlugin.SupplyCostType.ZULRAH_SCALE);
		}

		if (blowpipeDart == null)
		{
			return;
		}
		blowpipeDartUsageRemainder += getAmmoLossRate();
		int dartsUsed = (int) blowpipeDartUsageRemainder;
		blowpipeDartUsageRemainder -= dartsUsed;
		if (dartsUsed > 0)
		{
			record(blowpipeDart.itemId, dartsUsed, PvmToolsPlugin.SupplyCostType.AMMO);
		}
	}

	private double getAmmoLossRate()
	{
		if (capeItemId <= 0)
		{
			return 1d;
		}
		String capeName = itemManager.getItemComposition(capeItemId).getName().toLowerCase(Locale.ENGLISH);
		if (capeName.contains("assembler") || capeName.contains("dizana") || capeName.contains("ranging cape"))
		{
			return 0.20d;
		}
		if (capeName.contains("accumulator") || capeName.contains("max cape"))
		{
			return 0.28d;
		}
		if (capeName.contains("attractor"))
		{
			return 0.40d;
		}
		return 1d;
	}

	private boolean isThrownAmmo(int itemId)
	{
		String name = getItemName(itemId);
		return name.contains(" dart") || name.endsWith("dart")
			|| name.contains(" knife") || name.endsWith("knife")
			|| name.contains("thrownaxe") || name.contains("chinchompa");
	}

	private boolean isRangedAmmo(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}
		String name = getItemName(itemId);
		return isThrownAmmo(itemId)
			|| name.contains(" arrow") || name.endsWith("arrow")
			|| name.contains(" bolt") || name.endsWith("bolt")
			|| name.contains(" javelin") || name.endsWith("javelin");
	}

	private String getItemName(int itemId)
	{
		return itemManager.getItemComposition(itemId).getName().toLowerCase(Locale.ENGLISH);
	}

	private Item getEquipmentItem(ItemContainer equipment, int slot)
	{
		if (equipment == null || slot < 0 || slot >= equipment.getItems().length)
		{
			return new Item(-1, 0);
		}
		Item item = equipment.getItem(slot);
		return item == null ? new Item(-1, 0) : item;
	}

	private boolean isBlowpipe(int itemId)
	{
		return itemId == ItemID.TOXIC_BLOWPIPE || itemId == ItemID.BLAZING_BLOWPIPE;
	}

	private boolean isBlowpipeAnimation(int animation)
	{
		return animation == BLOWPIPE_ATTACK_ANIMATION || animation == BLOWPIPE_ORNAMENT_ATTACK_ANIMATION;
	}

	private boolean isItem(int itemId, int expected)
	{
		return itemId == expected;
	}

	private boolean isAnyItem(int itemId, int... expectedItems)
	{
		for (int expected : expectedItems)
		{
			if (itemId == expected)
			{
				return true;
			}
		}
		return false;
	}

	private void registerBlowpipeDart(int itemId, int projectileId)
	{
		blowpipeDartsByProjectile.put(projectileId, new BlowpipeDart(itemId));
	}

	private void record(int itemId, int quantity, PvmToolsPlugin.SupplyCostType type)
	{
		if (itemId > 0 && quantity > 0)
		{
			usageConsumer.record(itemId, quantity, type);
		}
	}

	private static Map<Integer, Integer> buildRunePouchItems()
	{
		Map<Integer, Integer> runes = new HashMap<>();
		runes.put(1, ItemID.AIR_RUNE);
		runes.put(2, ItemID.WATER_RUNE);
		runes.put(3, ItemID.EARTH_RUNE);
		runes.put(4, ItemID.FIRE_RUNE);
		runes.put(5, ItemID.MIND_RUNE);
		runes.put(6, ItemID.CHAOS_RUNE);
		runes.put(7, ItemID.DEATH_RUNE);
		runes.put(8, ItemID.BLOOD_RUNE);
		runes.put(9, ItemID.COSMIC_RUNE);
		runes.put(10, ItemID.NATURE_RUNE);
		runes.put(11, ItemID.LAW_RUNE);
		runes.put(12, ItemID.BODY_RUNE);
		runes.put(13, ItemID.SOUL_RUNE);
		runes.put(14, ItemID.ASTRAL_RUNE);
		runes.put(15, ItemID.MIST_RUNE);
		runes.put(16, ItemID.MUD_RUNE);
		runes.put(17, ItemID.DUST_RUNE);
		runes.put(18, ItemID.LAVA_RUNE);
		runes.put(19, ItemID.STEAM_RUNE);
		runes.put(20, ItemID.SMOKE_RUNE);
		runes.put(21, ItemID.WRATH_RUNE);
		runes.put(22, ItemID.SUNFIRE_RUNE);
		runes.put(23, ItemID.AETHER_RUNE);
		return runes;
	}

	@FunctionalInterface
	interface SupplyUsageConsumer
	{
		void record(int itemId, int quantity, PvmToolsPlugin.SupplyCostType type);
	}

	private static final class BlowpipeDart
	{
		private final int itemId;

		private BlowpipeDart(int itemId)
		{
			this.itemId = itemId;
		}
	}
}

package com.arber.pvmtools;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

final class PvmTaskHistoryEntry
{
	private static final String FIELD_SEPARATOR = "|";
	private static final String FIELD_SEPARATOR_PATTERN = "\\|";
	private static final int LEGACY_SERIALIZED_FIELD_COUNT = 14;
	private static final int SERIALIZED_FIELD_COUNT = 17;

	private final PvmTaskSnapshot task;
	private final long finishedMillis;

	PvmTaskHistoryEntry(PvmTaskSnapshot task, long finishedMillis)
	{
		this.task = task == null ? PvmTaskSnapshot.EMPTY : task;
		this.finishedMillis = Math.max(0L, finishedMillis);
	}

	PvmTaskSnapshot getTask()
	{
		return task;
	}

	long getFinishedMillis()
	{
		return finishedMillis;
	}

	boolean canMergeInterruptedTask(PvmTaskHistoryEntry other)
	{
		if (other == null
			|| !task.getName().equalsIgnoreCase(other.task.getName())
			|| !locationsMatch(task.getLocation(), other.task.getLocation()))
		{
			return false;
		}

		int thisInitial = task.getInitialAmount();
		int otherInitial = other.task.getInitialAmount();
		if (thisInitial > 0 && otherInitial > 0 && thisInitial != otherInitial)
		{
			return false;
		}

		return task.getAmount() > 5 || other.task.getAmount() > 5;
	}

	PvmTaskHistoryEntry merge(PvmTaskHistoryEntry other)
	{
		if (other == null)
		{
			return this;
		}

		PvmTaskSnapshot otherTask = other.task;
		String location = task.getLocation().isBlank() ? otherTask.getLocation() : task.getLocation();
		PvmTaskSnapshot mergedTask = new PvmTaskSnapshot(
			task.getName(),
			location,
			Math.min(task.getAmount(), otherTask.getAmount()),
			Math.max(task.getInitialAmount(), otherTask.getInitialAmount()),
			minPositive(task.getStartedMillis(), otherTask.getStartedMillis()),
			task.getElapsedMillis() + otherTask.getElapsedMillis(),
			task.getLootValue() + otherTask.getLootValue(),
			task.getSupplyCostValue() + otherTask.getSupplyCostValue(),
			task.getCombatXp() + otherTask.getCombatXp(),
			task.getSlayerXp() + otherTask.getSlayerXp(),
			task.getPotionDoseCount() + otherTask.getPotionDoseCount(),
			task.getFoodCount() + otherTask.getFoodCount(),
			task.getCannonballCount() + otherTask.getCannonballCount(),
			task.getRuneCount() + otherTask.getRuneCount(),
			task.getAmmoCount() + otherTask.getAmmoCount(),
			task.getZulrahScaleCount() + otherTask.getZulrahScaleCount());
		return new PvmTaskHistoryEntry(mergedTask, Math.max(finishedMillis, other.finishedMillis));
	}

	String serialize()
	{
		return encode(task.getName())
			+ FIELD_SEPARATOR + encode(task.getLocation())
			+ FIELD_SEPARATOR + task.getAmount()
			+ FIELD_SEPARATOR + task.getInitialAmount()
			+ FIELD_SEPARATOR + task.getStartedMillis()
			+ FIELD_SEPARATOR + task.getElapsedMillis()
			+ FIELD_SEPARATOR + task.getLootValue()
			+ FIELD_SEPARATOR + task.getSupplyCostValue()
			+ FIELD_SEPARATOR + task.getCombatXp()
			+ FIELD_SEPARATOR + task.getSlayerXp()
			+ FIELD_SEPARATOR + task.getPotionDoseCount()
			+ FIELD_SEPARATOR + task.getFoodCount()
			+ FIELD_SEPARATOR + task.getCannonballCount()
			+ FIELD_SEPARATOR + task.getRuneCount()
			+ FIELD_SEPARATOR + task.getAmmoCount()
			+ FIELD_SEPARATOR + task.getZulrahScaleCount()
			+ FIELD_SEPARATOR + finishedMillis;
	}

	static PvmTaskHistoryEntry deserialize(String serialized)
	{
		if (serialized == null || serialized.isBlank())
		{
			return null;
		}

		String[] fields = serialized.split(FIELD_SEPARATOR_PATTERN, -1);
		if (fields.length != LEGACY_SERIALIZED_FIELD_COUNT && fields.length != SERIALIZED_FIELD_COUNT)
		{
			return null;
		}

		try
		{
			boolean legacy = fields.length == LEGACY_SERIALIZED_FIELD_COUNT;
			PvmTaskSnapshot task = new PvmTaskSnapshot(
				decode(fields[0]),
				decode(fields[1]),
				Integer.parseInt(fields[2]),
				Integer.parseInt(fields[3]),
				Long.parseLong(fields[4]),
				Long.parseLong(fields[5]),
				Long.parseLong(fields[6]),
				Long.parseLong(fields[7]),
				Long.parseLong(fields[8]),
				Long.parseLong(fields[9]),
				Long.parseLong(fields[10]),
				Long.parseLong(fields[11]),
				Long.parseLong(fields[12]),
				legacy ? 0L : Long.parseLong(fields[13]),
				legacy ? 0L : Long.parseLong(fields[14]),
				legacy ? 0L : Long.parseLong(fields[15]));
			int finishedIndex = legacy ? 13 : 16;
			return task.isActive() ? new PvmTaskHistoryEntry(task, Long.parseLong(fields[finishedIndex])) : null;
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	private static String encode(String value)
	{
		return Base64.getUrlEncoder().withoutPadding().encodeToString(
			(value == null ? "" : value).getBytes(StandardCharsets.UTF_8));
	}

	private static String decode(String value)
	{
		return new String(Base64.getUrlDecoder().decode(value), StandardCharsets.UTF_8);
	}

	private static boolean locationsMatch(String first, String second)
	{
		return first.isBlank() || second.isBlank() || first.equalsIgnoreCase(second);
	}

	private static long minPositive(long first, long second)
	{
		if (first <= 0L)
		{
			return Math.max(0L, second);
		}
		if (second <= 0L)
		{
			return first;
		}
		return Math.min(first, second);
	}
}

package com.arber.pvmtools;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

final class PvmTaskPersonalBest
{
	enum Metric
	{
		TIME,
		PROFIT,
		XP
	}

	private final List<PvmTaskHistoryEntry> entries;
	private final PvmTaskHistoryEntry fastestEntry;
	private final PvmTaskHistoryEntry bestProfitEntry;
	private final PvmTaskHistoryEntry mostXpEntry;
	private final long averageElapsedMillis;
	private final long averageProfit;
	private final long averageXp;

	private PvmTaskPersonalBest(List<PvmTaskHistoryEntry> entries)
	{
		this.entries = entries;

		PvmTaskHistoryEntry fastest = null;
		PvmTaskHistoryEntry bestProfit = null;
		PvmTaskHistoryEntry mostXp = null;
		long totalElapsedMillis = 0L;
		long totalProfit = 0L;
		long totalXp = 0L;

		// History is newest first. Walking backwards preserves the older record on ties.
		for (int index = entries.size() - 1; index >= 0; index--)
		{
			PvmTaskHistoryEntry entry = entries.get(index);
			PvmTaskSnapshot task = entry.getTask();
			long taskXp = totalXp(task);

			if (task.getElapsedMillis() > 0L
				&& (fastest == null || task.getElapsedMillis() < fastest.getTask().getElapsedMillis()))
			{
				fastest = entry;
			}
			if (bestProfit == null || task.getNetProfit() > bestProfit.getTask().getNetProfit())
			{
				bestProfit = entry;
			}
			if (mostXp == null || taskXp > totalXp(mostXp.getTask()))
			{
				mostXp = entry;
			}

			totalElapsedMillis += task.getElapsedMillis();
			totalProfit += task.getNetProfit();
			totalXp += taskXp;
		}

		fastestEntry = fastest;
		bestProfitEntry = bestProfit;
		mostXpEntry = mostXp;
		int count = entries.size();
		averageElapsedMillis = count == 0 ? 0L : Math.round(totalElapsedMillis / (double) count);
		averageProfit = count == 0 ? 0L : Math.round(totalProfit / (double) count);
		averageXp = count == 0 ? 0L : Math.round(totalXp / (double) count);
	}

	static Map<String, PvmTaskPersonalBest> index(List<PvmTaskHistoryEntry> history)
	{
		Map<String, List<PvmTaskHistoryEntry>> groupedEntries = new LinkedHashMap<>();
		for (PvmTaskHistoryEntry entry : history)
		{
			groupedEntries
				.computeIfAbsent(taskKey(entry.getTask().getName()), ignored -> new ArrayList<>())
				.add(entry);
		}

		Map<String, PvmTaskPersonalBest> records = new LinkedHashMap<>();
		for (Map.Entry<String, List<PvmTaskHistoryEntry>> groupedEntry : groupedEntries.entrySet())
		{
			records.put(groupedEntry.getKey(), new PvmTaskPersonalBest(groupedEntry.getValue()));
		}
		return records;
	}

	static PvmTaskPersonalBest forTask(List<PvmTaskHistoryEntry> history, String taskName)
	{
		String requestedTask = taskKey(taskName);
		List<PvmTaskHistoryEntry> matchingEntries = new ArrayList<>();
		for (PvmTaskHistoryEntry entry : history)
		{
			if (taskKey(entry.getTask().getName()).equals(requestedTask))
			{
				matchingEntries.add(entry);
			}
		}
		return matchingEntries.isEmpty() ? null : new PvmTaskPersonalBest(matchingEntries);
	}

	int getTaskCount()
	{
		return entries.size();
	}

	long getFastestMillis()
	{
		return fastestEntry == null ? 0L : fastestEntry.getTask().getElapsedMillis();
	}

	long getBestProfit()
	{
		return bestProfitEntry == null ? 0L : bestProfitEntry.getTask().getNetProfit();
	}

	long getMostXp()
	{
		return mostXpEntry == null ? 0L : totalXp(mostXpEntry.getTask());
	}

	long getAverageElapsedMillis()
	{
		return averageElapsedMillis;
	}

	long getAverageProfit()
	{
		return averageProfit;
	}

	long getAverageXp()
	{
		return averageXp;
	}

	boolean isFirstRecord(PvmTaskHistoryEntry entry)
	{
		return entries.size() == 1 && entries.get(0) == entry;
	}

	EnumSet<Metric> getCurrentRecords(PvmTaskHistoryEntry entry)
	{
		EnumSet<Metric> records = EnumSet.noneOf(Metric.class);
		if (entry == fastestEntry)
		{
			records.add(Metric.TIME);
		}
		if (entry == bestProfitEntry)
		{
			records.add(Metric.PROFIT);
		}
		if (entry == mostXpEntry)
		{
			records.add(Metric.XP);
		}
		return records;
	}

	EnumSet<Metric> getNewRecords(PvmTaskHistoryEntry entry)
	{
		EnumSet<Metric> records = EnumSet.noneOf(Metric.class);
		if (entries.size() <= 1 || entries.get(0) != entry)
		{
			return records;
		}

		PvmTaskPersonalBest previousRecords =
			new PvmTaskPersonalBest(new ArrayList<>(entries.subList(1, entries.size())));
		PvmTaskSnapshot task = entry.getTask();
		if (task.getElapsedMillis() > 0L
			&& (previousRecords.getFastestMillis() == 0L
				|| task.getElapsedMillis() < previousRecords.getFastestMillis()))
		{
			records.add(Metric.TIME);
		}
		if (task.getNetProfit() > previousRecords.getBestProfit())
		{
			records.add(Metric.PROFIT);
		}
		if (totalXp(task) > previousRecords.getMostXp())
		{
			records.add(Metric.XP);
		}
		return records;
	}

	private static String taskKey(String taskName)
	{
		return taskName == null ? "" : taskName.trim().toLowerCase(Locale.ENGLISH);
	}

	private static long totalXp(PvmTaskSnapshot task)
	{
		return task.getCombatXp() + task.getSlayerXp();
	}
}

package com.arber.pvmtools;

final class PvmTaskSnapshot
{
	static final PvmTaskSnapshot EMPTY = new PvmTaskSnapshot("", "", 0, 0, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L);

	private final String name;
	private final String location;
	private final int amount;
	private final int initialAmount;
	private final long startedMillis;
	private final long elapsedMillis;
	private final long lootValue;
	private final long supplyCostValue;
	private final long combatXp;
	private final long slayerXp;
	private final long potionDoseCount;
	private final long foodCount;
	private final long cannonballCount;
	private final long runeCount;
	private final long ammoCount;
	private final long zulrahScaleCount;

	PvmTaskSnapshot(
		String name,
		String location,
		int amount,
		int initialAmount,
		long startedMillis,
		long elapsedMillis,
		long lootValue,
		long supplyCostValue,
		long combatXp,
		long slayerXp,
		long potionDoseCount,
		long foodCount,
		long cannonballCount)
	{
		this(name, location, amount, initialAmount, startedMillis, elapsedMillis, lootValue,
			supplyCostValue, combatXp, slayerXp, potionDoseCount, foodCount, cannonballCount,
			0L, 0L, 0L);
	}

	PvmTaskSnapshot(
		String name,
		String location,
		int amount,
		int initialAmount,
		long startedMillis,
		long elapsedMillis,
		long lootValue,
		long supplyCostValue,
		long combatXp,
		long slayerXp,
		long potionDoseCount,
		long foodCount,
		long cannonballCount,
		long runeCount,
		long ammoCount,
		long zulrahScaleCount)
	{
		this.name = name == null ? "" : name;
		this.location = location == null ? "" : location;
		this.amount = Math.max(0, amount);
		this.initialAmount = Math.max(0, initialAmount);
		this.startedMillis = Math.max(0L, startedMillis);
		this.elapsedMillis = Math.max(0L, elapsedMillis);
		this.lootValue = Math.max(0L, lootValue);
		this.supplyCostValue = Math.max(0L, supplyCostValue);
		this.combatXp = Math.max(0L, combatXp);
		this.slayerXp = Math.max(0L, slayerXp);
		this.potionDoseCount = Math.max(0L, potionDoseCount);
		this.foodCount = Math.max(0L, foodCount);
		this.cannonballCount = Math.max(0L, cannonballCount);
		this.runeCount = Math.max(0L, runeCount);
		this.ammoCount = Math.max(0L, ammoCount);
		this.zulrahScaleCount = Math.max(0L, zulrahScaleCount);
	}

	boolean isActive()
	{
		return !name.isBlank();
	}

	String getName()
	{
		return name;
	}

	String getLocation()
	{
		return location;
	}

	int getAmount()
	{
		return amount;
	}

	int getInitialAmount()
	{
		return initialAmount;
	}

	long getStartedMillis()
	{
		return startedMillis;
	}

	long getElapsedMillis()
	{
		return elapsedMillis;
	}

	long getLootValue()
	{
		return lootValue;
	}

	long getSupplyCostValue()
	{
		return supplyCostValue;
	}

	long getNetProfit()
	{
		return lootValue - supplyCostValue;
	}

	long getCombatXp()
	{
		return combatXp;
	}

	long getSlayerXp()
	{
		return slayerXp;
	}

	long getPotionDoseCount()
	{
		return potionDoseCount;
	}

	long getFoodCount()
	{
		return foodCount;
	}

	long getCannonballCount()
	{
		return cannonballCount;
	}

	long getRuneCount()
	{
		return runeCount;
	}

	long getAmmoCount()
	{
		return ammoCount;
	}

	long getZulrahScaleCount()
	{
		return zulrahScaleCount;
	}

	int getKilled()
	{
		return initialAmount > 0 ? Math.max(0, initialAmount - amount) : 0;
	}
}

