	private void addStatsNavigation()
	{
		if (statsNavigationButton != null)
		{
			return;
		}

		statsPanel = new PvmToolsStatsPanel(this);
		BufferedImage icon = loadNavigationIcon();
		statsNavigationButton = NavigationButton.builder()
				.tooltip("PvM Toolkit Stats")
			.icon(icon)
			.panel(statsPanel)
			.priority(STATS_NAVIGATION_PRIORITY)
			.build();
		clientToolbar.addNavigation(statsNavigationButton);
		if (isDeveloperMode())
		{
			SwingUtilities.invokeLater(() -> clientToolbar.openPanel(statsNavigationButton));
		}
	}

	private void removeStatsNavigation()
	{
		if (statsNavigationButton != null)
		{
			clientToolbar.removeNavigation(statsNavigationButton);
			statsNavigationButton = null;
		}

		statsPanel = null;
	}

	private BufferedImage loadNavigationIcon()
	{
		try
		{
			BufferedImage icon = ImageUtil.loadImageResource(PvmToolsPlugin.class, "/com/arber/pvmtools/icon.png");
			if (icon == null)
			{
				icon = ImageUtil.loadImageResource(PvmToolsPlugin.class, "/icon.png");
			}

			if (icon != null)
			{
				return ImageUtil.resizeImage(icon, STATS_NAVIGATION_ICON_SIZE, STATS_NAVIGATION_ICON_SIZE, true);
			}
		}
		catch (RuntimeException ignored)
		{
			// Missing resources should never prevent the plugin itself from starting.
		}

		return itemManager.getImage(ItemID.COINS_995);
	}

	private boolean isDeveloperMode()
	{
		return System.getProperty("sun.java.command", "").contains("--developer-mode");
	}

	private void updateUpdateScroll()
	{
		String version = getPluginVersion();
		String seenVersion = configManager.getConfiguration(
			PvmToolsConfig.GROUP,
			SEEN_UPDATE_SCROLL_VERSION_KEY);
		if (!shouldShowUpdateScroll(
			version,
			seenVersion,
			config.dontShowUpdateScroll(),
			updateScrollPreviewRequested))
		{
			return;
		}

		if (!isUpdateScrollWorldReady())
		{
			updateScrollReadyTicks = 0;
			return;
		}

		if (updateScrollVisible || updateScrollDisplayScheduled)
		{
			return;
		}

		updateScrollReadyTicks++;
		if (updateScrollReadyTicks < UPDATE_SCROLL_READY_TICKS)
		{
			return;
		}

		showUpdateScroll();
	}

	static boolean shouldShowUpdateScroll(
		String currentVersion,
		String seenVersion,
		boolean dontShowUpdates,
		boolean previewRequested)
	{
		if (previewRequested)
		{
			return true;
		}
		return !dontShowUpdates
			&& currentVersion != null
			&& !currentVersion.equals(seenVersion);
	}

	private boolean isUpdateScrollWorldReady()
	{
		if (!started || !isLoggedIn() || client.getLocalPlayer() == null || client.getCanvas() == null)
		{
			return false;
		}

		return !isClickToPlayScreenVisible();
	}

	private boolean isClickToPlayScreenVisible()
	{
		Widget clickToPlayRoot = client.getWidget(InterfaceID.WELCOME_SCREEN, 0);
		return clickToPlayRoot != null
			&& !clickToPlayRoot.isHidden()
			&& clickToPlayRoot.getWidth() > 0
			&& clickToPlayRoot.getHeight() > 0;
	}

	private void showUpdateScroll()
	{
		Canvas canvas = client.getCanvas();
		if (canvas == null)
		{
			return;
		}

		String version = getPluginVersion();
		int generation = ++updateScrollGeneration;
		updateScrollDisplayScheduled = true;
		SwingUtilities.invokeLater(() ->
		{
			if (!started || generation != updateScrollGeneration)
			{
				updateScrollDisplayScheduled = false;
				return;
			}

			boolean shown = updatePanel.showPanel(
				canvas,
				version,
				UPDATE_SCROLL_NOTES,
				() -> dismissUpdateScroll(version),
				() -> disableUpdateScroll(version));
			updateScrollVisible = shown;
			updateScrollDisplayScheduled = false;
			if (!shown)
			{
				updateScrollReadyTicks = 0;
			}
		});
	}

	private void dismissUpdateScroll(String version)
	{
		updateScrollVisible = false;
		updateScrollPreviewRequested = false;
		updateScrollReadyTicks = 0;
		configManager.setConfiguration(
			PvmToolsConfig.GROUP,
			SEEN_UPDATE_SCROLL_VERSION_KEY,
			version);
	}

	private void disableUpdateScroll(String version)
	{
		configManager.setConfiguration(
			PvmToolsConfig.GROUP,
			"dontShowUpdateScroll",
			true);
		dismissUpdateScroll(version);
		refreshOpenDontShowCheckbox();
	}

	private void refreshOpenDontShowCheckbox()
	{
		SwingUtilities.invokeLater(() ->
		{
			Canvas canvas = client.getCanvas();
			JRootPane rootPane = canvas == null ? null : SwingUtilities.getRootPane(canvas);
			if (rootPane != null)
			{
				selectDontShowCheckbox(rootPane);
			}
		});
	}

	private boolean selectDontShowCheckbox(Component component)
	{
		if (!(component instanceof Container))
		{
			return false;
		}

		Component[] children = ((Container) component).getComponents();
		JLabel matchingLabel = null;
		JCheckBox matchingCheckbox = null;
		for (Component child : children)
		{
			if (child instanceof JLabel
				&& "Don't show updates".equals(((JLabel) child).getText()))
			{
				matchingLabel = (JLabel) child;
			}
			else if (child instanceof JCheckBox)
			{
				matchingCheckbox = (JCheckBox) child;
			}
		}

		if (matchingLabel != null && matchingCheckbox != null)
		{
			matchingCheckbox.setSelected(true);
			matchingCheckbox.repaint();
			return true;
		}

		for (Component child : children)
		{
			if (selectDontShowCheckbox(child))
			{
				return true;
			}
		}
		return false;
	}

	private void migrateUpdateScrollSetting()
	{
		String oldValue = configManager.getConfiguration(
			PvmToolsConfig.GROUP,
			"showUpdateScroll");
		String newValue = configManager.getConfiguration(
			PvmToolsConfig.GROUP,
			"dontShowUpdateScroll");
		if (oldValue != null && newValue == null)
		{
			configManager.setConfiguration(
				PvmToolsConfig.GROUP,
				"dontShowUpdateScroll",
				!Boolean.parseBoolean(oldValue));
		}

		configManager.unsetConfiguration(
			PvmToolsConfig.GROUP,
			"showUpdateScroll");
	}

	private void migratePriceSourceSettings()
	{
		if (configManager.getConfiguration(PvmToolsConfig.GROUP, "supplyPriceSource") != null)
		{
			return;
		}

		ToolkitMarketPriceSource supplySource = config.priceSource() == ToolkitPriceSource.RUNELITE
			? ToolkitMarketPriceSource.RUNELITE
			: ToolkitMarketPriceSource.GE_GUIDE;
		configManager.setConfiguration(PvmToolsConfig.GROUP, "supplyPriceSource", supplySource);
	}

	private void hideUpdateScroll()
	{
		updateScrollGeneration++;
		updateScrollVisible = false;
		updateScrollDisplayScheduled = false;
		updateScrollPreviewRequested = false;
		if (updatePanel != null)
		{
			updatePanel.hidePanel();
		}
	}

	private String getPluginVersion()
	{
		if (pluginVersion != null)
		{
			return pluginVersion;
		}

		try (InputStream stream = PvmToolsPlugin.class.getResourceAsStream("plugin.properties"))
		{
			if (stream != null)
			{
				Properties properties = new Properties();
				properties.load(stream);
				String resourceVersion = properties.getProperty("version");
				if (resourceVersion != null && !resourceVersion.isBlank())
				{
					pluginVersion = resourceVersion;
					return pluginVersion;
				}
			}
		}
		catch (IOException exception)
		{
			log.debug("Unable to read the bundled PvM Toolkit version", exception);
		}

		PluginHubManifest.DisplayData displayData =
			ExternalPluginManager.getDisplayData(PvmToolsPlugin.class);
		if (displayData != null
			&& displayData.getVersion() != null
			&& !displayData.getVersion().isBlank())
		{
			pluginVersion = displayData.getVersion();
			return pluginVersion;
		}

		pluginVersion = "dev";
		return pluginVersion;
	}

	@Override
	protected void startUp()
	{
		try
		{
			started = true;
			trackerPersistenceLastMillis = System.currentTimeMillis();
			supplyUsageTracker = new PvmSupplyUsageTracker(client, itemManager, this::recordTrackedSupplyUsage);
			toolkitUiGeneration++;
			updateScrollVisible = false;
			updateScrollDisplayScheduled = false;
			updateScrollPreviewRequested = false;
			updateScrollReadyTicks = 0;
			updateScrollGeneration++;
			slayerTaskObservedActive = false;
			pendingSlayerTaskCompletionTicks = 0;
			clearPluginInfoBoxes();
			hooks.registerRenderableDrawListener(drawListener);
			overlayManager.remove(warningOverlay);
			overlayManager.add(warningOverlay);
			overlayManager.remove(groundItemHighlightOverlay);
			overlayManager.add(groundItemHighlightOverlay);
			overlayManager.remove(groundItemLifetimeTextOverlay);
			overlayManager.add(groundItemLifetimeTextOverlay);
			resetFamilyState();
			initializeTrackerDefaults();
			loadTrackerValues();
			loadStatsValues();
			beginXpTrackerInitialization();
			loadCombatLootExclusions();
			reloadIgnoredSupplyItems();
			loadCurrentSlayerTaskState();
			loadSlayerTaskHistory();
			migratePriceSourceSettings();
			migrateUpdateScrollSetting();
			addStatsNavigation();
			initializeClientStateLater();
		}
		catch (RuntimeException exception)
		{
			shutDown();
			throw exception;
		}
	}

	private void initializeTrackerDefaults()
	{
		if (config.trackerDefaultsInitialized())
		{
			return;
		}

		configManager.setConfiguration(PvmToolsConfig.GROUP, "trackerMode", TrackerPersistenceMode.FOREVER);
		configManager.setConfiguration(PvmToolsConfig.GROUP, "clanLootTracker", true);
		configManager.setConfiguration(PvmToolsConfig.GROUP, "publicSupplyCostTracker", true);
		configManager.setConfiguration(PvmToolsConfig.GROUP, "channelCombatXpTracker", true);
		configManager.setConfiguration(PvmToolsConfig.GROUP, "privateSlayerXpTracker", true);
		configManager.setConfiguration(PvmToolsConfig.GROUP, "topXpSkillTracker", true);
		configManager.setConfiguration(PvmToolsConfig.GROUP, TRACKER_DEFAULTS_INITIALIZED_KEY, true);
	}

	@Override
	protected void shutDown()
	{
		started = false;
		runShutdownStep("save the current Slayer task", () ->
		{
			pauseCurrentSlayerTaskTimer();
			persistCurrentSlayerTaskState();
			checkpointStatsPersistence(System.currentTimeMillis(), true);
			checkpointTrackerPersistence(System.currentTimeMillis(), true);
		});
		runShutdownStep("hide the update scroll", this::hideUpdateScroll);
		runShutdownStep("unregister the render listener", () -> hooks.unregisterRenderableDrawListener(drawListener));
		runShutdownStep("remove the warning overlay", () -> overlayManager.remove(warningOverlay));
		runShutdownStep("remove the ground item highlight overlay", () -> overlayManager.remove(groundItemHighlightOverlay));
		runShutdownStep("remove the ground item timer overlay", () -> overlayManager.remove(groundItemLifetimeTextOverlay));
		runShutdownStep("reset ground item timers", groundItemLifetimeTextOverlay::reset);
		runShutdownStep("close the warning popup", this::closeWarningPopupInterface);
		runShutdownStep("remove the side panel", this::removeStatsNavigation);
		runShutdownStep("release toolkit UI ownership", this::releaseToolkitUiOwnershipLater);
		runShutdownStep("clear timers", this::clearTimers);
		runShutdownStep("remove the inventory infobox", this::removeInventoryInfoBox);
		runShutdownStep("remove plugin infoboxes", this::clearPluginInfoBoxes);
		runShutdownStep("clear NPC drop tracking", this::clearNpcDropTracking);
		runShutdownStep("clear item name caches", () ->
		{
			itemDisplayNames.clear();
			pendingItemDisplayNames.clear();
		});
		runShutdownStep("reset supply usage tracking", () ->
		{
			if (supplyUsageTracker != null)
			{
				supplyUsageTracker.reset();
			}
		});
		runShutdownStep("reset runtime state", this::resetFamilyState);
	}

	private void runShutdownStep(String description, Runnable step)
	{
		try
		{
			step.run();
		}
		catch (RuntimeException exception)
		{
			log.warn("Unable to {} while stopping PvM Toolkit", description, exception);
		}
	}

	private void initializeClientStateLater()
	{
		clientThread.invokeLater(() ->
		{
			if (!started)
			{
				return;
			}

			reconcileLifetimeTrackers();
			ensureToolkitOwnerAvailable();
			if (!isToolkitUiManuallySelected() && !ownsToolkitUi())
			{
				setToolkitUiOwner(TOOLKIT_UI_OWNER_PVM, TOOLKIT_UI_SOURCE_ACTIVITY);
			}
			syncSlayerTaskFromRuneLite();
			syncAllTimers();
			cacheTrackedItemDisplayNames();
			refreshStatsPanel();
			updateChatTabTrackers();
			if (isLoggedIn() && supplyUsageTracker != null)
			{
				supplyUsageTracker.initialize();
				supplyUsageTracker.rebaseMagicXpBaseline();
			}
			initializeInventoryCurrencyCounts();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGING_IN || event.getGameState() == GameState.HOPPING
			|| event.getGameState() == GameState.CONNECTION_LOST)
		{
			beginXpTrackerInitialization();
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			if (supplyUsageTracker != null)
			{
				supplyUsageTracker.initialize();
				supplyUsageTracker.rebaseMagicXpBaseline();
			}
			initializeInventoryCurrencyCounts();
			syncAllTimers();
			cacheTrackedItemDisplayNames();
			refreshStatsPanel();
			return;
		}

		if (isResetGameState(event.getGameState()))
		{
			if (supplyUsageTracker != null)
			{
				supplyUsageTracker.reset();
			}
			hideUpdateScroll();
			updateScrollReadyTicks = 0;
			slayerTaskObservedActive = false;
			pendingSlayerTaskCompletionTicks = 0;
			pauseCurrentSlayerTaskTimer();
			checkpointStatsPersistence(System.currentTimeMillis(), true);
			checkpointTrackerPersistence(System.currentTimeMillis(), true);
			persistCurrentSlayerTaskState();
			if (groundItemLifetimeTextOverlay != null)
			{
				groundItemLifetimeTextOverlay.reset();
			}
			restoreChatTabOverrides();
			clearNpcDropTracking();
			clearTimers();
			removeInventoryInfoBox();
			resetFamilyState();
		}
	}

