		switch (event.getVarbitId())
		{
			case VarbitID.NZONE_OVERLOAD_POTION_EFFECTS:
			case VarbitID.RAIDS_OVERLOAD_TIMER:
			case VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS:
