				return config.clanLootTracker() && npcLootValue > 0;
			case SUPPLY_COST:
				return config.publicSupplyCostTracker() && supplyCostValue > 0;
			case COMBAT_XP:
				return config.channelCombatXpTracker() && getCombatXpGained() > 0;
			case SLAYER_XP:
