	private void releaseToolkitUiOwnershipLater()
	{
		int generation = toolkitUiGeneration;
		clientThread.invokeLater(() ->
		{
			if (started || generation != toolkitUiGeneration)
			{
				return;
			}

			restoreChatTabOverrides();
			removeInventoryInfoBox();
			if (!ownsToolkitUi())
			{
