		for (PvmToolsStatsPeriod period : PvmToolsStatsPeriod.values())
		{
			getStats(period).addCombatLoot(sourceName, combatLevel, drops, timestamp, countKill);
			persistStatsValue(period);
		}
		refreshStatsPanel();
