	private boolean isOtherToolkitUiOwnerActive()
	{
		return TOOLKIT_UI_OWNER_SKILLING.equals(configManager.getConfiguration(TOOLKIT_UI_COORDINATION_GROUP, TOOLKIT_UI_OWNER_KEY))
