	private void showLootLog()
	{
		taskLogVisible = false;
		lootLogVisible = true;
		visibleTrackedLootCount = LOOT_LOG_PAGE_SIZE;
		refreshLootLog();
		showContent(lootLogContent);
		refresh();
	}

	private void refreshLootLog()
	{
		PvmToolsStats stats = panelSnapshot.getStats();
		List<PvmLootSourceStat> sources = stats.getCombatLootSources();
		lootLogContent.removeAll();

		JLabel title = new JLabel("Combat Loot - " + panelSnapshot.getPeriod().getDisplayName(), SwingConstants.CENTER);
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setAlignmentX(CENTER_ALIGNMENT);
		lootLogContent.add(title);
		lootLogContent.add(Box.createVerticalStrut(8));

		JButton backButton = actionButton("Back to Stats", ColorScheme.DARKER_GRAY_COLOR, Color.WHITE);
		backButton.addActionListener(e -> showMainPanel());
		lootLogContent.add(buttonRow(backButton));
		lootLogContent.add(Box.createVerticalStrut(8));

		long totalKills = 0L;
		long countedLoot = 0L;
		long supplyCost = 0L;
		for (PvmLootSourceStat source : sources)
		{
			totalKills += source.getKills();
			countedLoot += panelSnapshot.getCountedLootValue(source);
			supplyCost += source.getSupplyCostValue();
		}
		JPanel summary = statsCard("Combat Loot Summary");
		addStaticRow(summary, "Total drops", formatGp(stats.getCombatLootValue()), MUTED_TEXT);
		addStaticRow(summary, "Counted loot", formatGp(countedLoot), PROFIT_COLOR);
		addStaticRow(summary, "Supply cost", formatGp(supplyCost), COST_COLOR);
		long totalProfit = countedLoot - supplyCost;
		addStaticRow(summary, "Profit", formatSignedGp(totalProfit), totalProfit >= 0L ? PROFIT_COLOR : COST_COLOR);
		addStaticRow(summary, "Monsters", formatCount(sources.size()), MUTED_TEXT);
		addStaticRow(summary, "Kills", formatCount(totalKills), MUTED_TEXT);
		lootLogContent.add(summary);
		lootLogContent.add(Box.createVerticalStrut(8));

		if (sources.isEmpty())
		{
			JPanel emptyCard = statsCard("No Combat Loot Yet");
			addPlainLine(emptyCard, "Pick up a new NPC drop to start its loot record.", MUTED_TEXT);
			addPlainLine(emptyCard, "Only loot collected after this update appears here.", MUTED_TEXT);
			lootLogContent.add(emptyCard);
		}
		else
		{
			int displayedSources = Math.min(sources.size(), visibleTrackedLootCount);
			for (PvmLootSourceStat source : sources.subList(0, displayedSources))
			{
				lootLogContent.add(combatLootSourceCard(source));
				lootLogContent.add(Box.createVerticalStrut(6));
			}

			if (displayedSources < sources.size())
			{
				int remaining = sources.size() - displayedSources;
				JButton showMoreButton = actionButton(
					"Show More (" + remaining + " left)",
					ColorScheme.DARKER_GRAY_COLOR,
					Color.WHITE);
				showMoreButton.addActionListener(e ->
				{
					visibleTrackedLootCount += LOOT_LOG_PAGE_SIZE;
					refreshLootLog();
				});
				lootLogContent.add(buttonRow(showMoreButton));
			}
		}

		lootLogContent.revalidate();
		lootLogContent.repaint();
	}

	private JPanel combatLootSourceCard(PvmLootSourceStat source)
	{
		String title = source.getKills() > 0L
			? source.getName() + " x " + formatCount(source.getKills())
			: source.getName();
		JPanel card = statsCard(shorten(title, 27));
		String level = source.getCombatLevel() > 0 ? "Level " + source.getCombatLevel() + " | " : "";
		addPlainLine(card, level + formatCount(source.getDrops().size()) + " item types", MUTED_TEXT);
		long countedValue = panelSnapshot.getCountedLootValue(source);
		long profit = countedValue - source.getSupplyCostValue();
		addStaticRow(card, "Total", formatGp(source.getTotalValue()), MUTED_TEXT);
		addStaticRow(card, "Counted", formatGp(countedValue), PROFIT_COLOR);
		addStaticRow(card, "Cost", formatGp(source.getSupplyCostValue()), COST_COLOR);
		addStaticRow(card, "Profit", formatSignedGp(profit), profit >= 0L ? PROFIT_COLOR : COST_COLOR);
		if (source.getLastLootMillis() > 0L)
		{
			addPlainLine(card, "Last: " + TASK_DATE_FORMATTER.format(Instant.ofEpochMilli(source.getLastLootMillis())), MUTED_TEXT);
		}

		JPanel itemGrid = new JPanel(new GridLayout(0, 4, 3, 3));
		itemGrid.setBackground(CARD_BACKGROUND);
		itemGrid.setBorder(BorderFactory.createEmptyBorder(5, 0, 2, 0));
		for (PvmDropStat drop : source.getDrops())
		{
			itemGrid.add(combatLootItemCell(source, drop));
		}
		card.add(itemGrid);
		return card;
	}

	private JPanel combatLootItemCell(PvmLootSourceStat source, PvmDropStat drop)
	{
		boolean excluded = panelSnapshot.isLootExcluded(source.getName(), drop.getItemId());
		JPanel cell = new JPanel(new BorderLayout());
		cell.setBackground(excluded ? new Color(55, 35, 35) : ColorScheme.DARKER_GRAY_COLOR);
		cell.setPreferredSize(new Dimension(58, 52));
		cell.setBorder(BorderFactory.createLineBorder(excluded ? COST_COLOR.darker() : ColorScheme.DARK_GRAY_COLOR));

		JLabel icon = new JLabel("", SwingConstants.CENTER);
		String itemName = plugin.getItemDisplayName(drop.getItemId());
		icon.setToolTipText("<html>" + itemName + "<br>Quantity: " + formatCount(drop.getQuantity())
			+ "<br>Value: " + formatGp(drop.getValue())
			+ "<br><b>Click to " + (excluded ? "include" : "exclude") + " for " + source.getName() + "</b></html>");
		icon.setEnabled(!excluded);
		plugin.addItemImageTo(icon, drop.getItemId(), (int) Math.min(Integer.MAX_VALUE, drop.getQuantity()));
		MouseAdapter toggleListener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent event)
			{
				plugin.toggleCombatLootItemExcluded(source.getName(), drop.getItemId());
			}
		};
		icon.addMouseListener(toggleListener);
		cell.addMouseListener(toggleListener);
		cell.add(icon, BorderLayout.CENTER);
		return cell;
	}

	private void showContent(JPanel content)
	{
		contentContainer.removeAll();
		contentContainer.add(content, BorderLayout.CENTER);
		contentContainer.revalidate();
		contentContainer.repaint();
	}

	private void refreshTaskLog(boolean force)
	{
		List<PvmTaskHistoryEntry> history = panelSnapshot.getTaskHistory();
		long newestFinishedMillis = history.isEmpty() ? 0L : history.get(0).getFinishedMillis();
		if (!force
			&& history.size() == renderedTaskHistorySize
			&& newestFinishedMillis == renderedNewestTaskFinishedMillis
			&& visibleTaskHistoryCount == renderedTaskHistoryVisibleCount)
		{
			return;
		}

		renderedTaskHistorySize = history.size();
		renderedNewestTaskFinishedMillis = newestFinishedMillis;
		renderedTaskHistoryVisibleCount = visibleTaskHistoryCount;
		taskLogContent.removeAll();

		JLabel title = new JLabel("Slayer Task Log", SwingConstants.CENTER);
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setAlignmentX(CENTER_ALIGNMENT);
		taskLogContent.add(title);
		taskLogContent.add(Box.createVerticalStrut(8));

		JButton backButton = actionButton("Back to Stats", ColorScheme.DARKER_GRAY_COLOR, Color.WHITE);
		backButton.addActionListener(e -> showMainPanel());
		taskLogContent.add(buttonRow(backButton));
		taskLogContent.add(Box.createVerticalStrut(8));

		addTaskLogSummary(history);
		taskLogContent.add(Box.createVerticalStrut(8));
		if (history.isEmpty())
		{
			JPanel emptyCard = statsCard("Task History");
			addPlainLine(emptyCard, "Finished tasks will appear here.", MUTED_TEXT);
			taskLogContent.add(emptyCard);
		}
		else
		{
			int displayedTasks = Math.min(history.size(), visibleTaskHistoryCount);
			Map<String, PvmTaskPersonalBest> personalBests = PvmTaskPersonalBest.index(history);
			for (PvmTaskHistoryEntry entry : history.subList(0, displayedTasks))
			{
				taskLogContent.add(taskLogCard(
					entry,
					personalBests.get(taskRecordKey(entry.getTask().getName()))));
				taskLogContent.add(Box.createVerticalStrut(8));
			}

			if (displayedTasks < history.size())
			{
				int remainingTasks = history.size() - displayedTasks;
				JButton showMoreButton = actionButton(
					"Show More (" + remainingTasks + " left)",
					ColorScheme.DARKER_GRAY_COLOR,
					Color.WHITE);
				showMoreButton.addActionListener(e ->
				{
					visibleTaskHistoryCount += TASK_LOG_PAGE_SIZE;
					refreshTaskLog(true);
				});
				taskLogContent.add(buttonRow(showMoreButton));
				taskLogContent.add(Box.createVerticalStrut(6));
			}
		}

		JButton clearButton = actionButton("Clear Slayer Log", new Color(105, 42, 42), Color.WHITE);
		clearButton.setEnabled(!history.isEmpty());
		clearButton.setToolTipText("Permanently delete all saved Slayer task history.");
		clearButton.addActionListener(e -> confirmClearTaskHistory());
		taskLogContent.add(buttonRow(clearButton));
		taskLogContent.revalidate();
		taskLogContent.repaint();
	}

	private void addTaskLogSummary(List<PvmTaskHistoryEntry> history)
	{
		long totalTime = 0L;
		long totalLoot = 0L;
		long totalCost = 0L;
		long totalCombatXp = 0L;
		long totalSlayerXp = 0L;
		for (PvmTaskHistoryEntry entry : history)
		{
			PvmTaskSnapshot task = entry.getTask();
			totalTime += task.getElapsedMillis();
			totalLoot += task.getLootValue();
			totalCost += task.getSupplyCostValue();
			totalCombatXp += task.getCombatXp();
			totalSlayerXp += task.getSlayerXp();
		}

		long totalProfit = totalLoot - totalCost;
		JPanel summary = statsCard("History Summary");
		addStaticRow(summary, "Tasks", formatCount(history.size()), MUTED_TEXT);
		addStaticRow(summary, "Time", formatDuration(totalTime), MUTED_TEXT);
		addStaticRow(summary, "Loot", formatGp(totalLoot), PROFIT_COLOR);
		addStaticRow(summary, "Supplies", formatGp(totalCost), COST_COLOR);
		addStaticRow(summary, "Profit", formatSignedGp(totalProfit), totalProfit >= 0 ? PROFIT_COLOR : COST_COLOR);
		addStaticRow(summary, "Combat XP", formatXp(totalCombatXp), XP_COLOR);
		addStaticRow(summary, "Slayer XP", formatXp(totalSlayerXp), XP_COLOR);
		addStaticRow(
			summary,
			"Monsters tracked",
			formatCount(PvmTaskPersonalBest.index(history).size()),
			PB_COLOR);
		taskLogContent.add(summary);
	}

	private JPanel taskLogCard(PvmTaskHistoryEntry entry, PvmTaskPersonalBest personalBest)
	{
		PvmTaskSnapshot task = entry.getTask();
		JPanel card = statsCard(task.getName());
		addPersonalBestBanner(card, entry, personalBest);
		String finished = entry.getFinishedMillis() > 0L
			? TASK_DATE_FORMATTER.format(Instant.ofEpochMilli(entry.getFinishedMillis()))
			: "Unknown date";
		String location = task.getLocation().isBlank() ? finished : task.getLocation() + " | " + finished;
		addPlainLine(card, location, MUTED_TEXT);

		JPanel metrics = tileGrid();
		addStaticTile(metrics, formatTaskProgressCompact(task), "Kills", MUTED_TEXT);
		addStaticTile(metrics, formatDurationCompact(task.getElapsedMillis()), "Time", MUTED_TEXT);
		addStaticTile(metrics, formatCompactCount(task.getLootValue()), "Loot", PROFIT_COLOR);
		addStaticTile(metrics, formatCompactCount(task.getSupplyCostValue()), "Supplies", COST_COLOR);
		addStaticTile(metrics, formatSignedGpShort(task.getNetProfit()), "Profit", task.getNetProfit() >= 0 ? PROFIT_COLOR : COST_COLOR);
		addStaticTile(metrics, formatCompactCount(task.getCombatXp() + task.getSlayerXp()), "Total XP", XP_COLOR);
		card.add(metrics);

		addStaticRow(card, "Combat XP", formatCompactCount(task.getCombatXp()), XP_COLOR);
		addStaticRow(card, "Slayer XP", formatCompactCount(task.getSlayerXp()), XP_COLOR);
		addPersonalBestComparison(card, personalBest);
		long potions = (task.getPotionDoseCount() + 3L) / 4L;
		addPlainLine(
			card,
			"Potions " + formatCount(potions) + " | Food " + formatCount(task.getFoodCount()) + " | Balls " + formatCount(task.getCannonballCount()),
			MUTED_TEXT);
		addPlainLine(
			card,
			"Runes " + formatCount(task.getRuneCount()) + " | Ammo " + formatCount(task.getAmmoCount()) + " | Scales " + formatCount(task.getZulrahScaleCount()),
			MUTED_TEXT);
		return card;
	}

	private void addPersonalBestBanner(
		JPanel card,
		PvmTaskHistoryEntry entry,
		PvmTaskPersonalBest personalBest)
	{
		if (personalBest == null)
		{
			return;
		}

		String text;
		if (personalBest.isFirstRecord(entry))
		{
			text = "FIRST RECORD";
		}
		else
		{
			EnumSet<PvmTaskPersonalBest.Metric> newRecords = personalBest.getNewRecords(entry);
			if (!newRecords.isEmpty())
			{
				text = "NEW PB  |  " + formatRecordMetrics(newRecords);
			}
			else
			{
				EnumSet<PvmTaskPersonalBest.Metric> currentRecords =
					personalBest.getCurrentRecords(entry);
				if (currentRecords.isEmpty())
				{
					return;
				}
				text = "PB  |  " + formatRecordMetrics(currentRecords);
			}
		}

		JLabel label = new JLabel(text, SwingConstants.CENTER);
		label.setForeground(PB_COLOR);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setBorder(BorderFactory.createEmptyBorder(5, 4, 5, 4));
		card.add(centeredRow(label, PB_BACKGROUND));
		card.add(Box.createVerticalStrut(3));
	}

	private void addPersonalBestComparison(JPanel card, PvmTaskPersonalBest personalBest)
	{
		if (personalBest == null || personalBest.getTaskCount() <= 1)
		{
			return;
		}

		JPanel comparison = new JPanel();
		comparison.setLayout(new BoxLayout(comparison, BoxLayout.Y_AXIS));
		comparison.setBackground(new Color(29, 29, 29));
		comparison.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(78, 62, 24)),
			BorderFactory.createEmptyBorder(4, 4, 5, 4)));
		comparison.setMaximumSize(new Dimension(Integer.MAX_VALUE, 108));

		JLabel title = new JLabel("Personal Bests", SwingConstants.CENTER);
		title.setForeground(PB_COLOR);
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setAlignmentX(CENTER_ALIGNMENT);
		comparison.add(title);
		comparison.add(Box.createVerticalStrut(3));

		JPanel table = new JPanel(new GridLayout(0, 3, 3, 2));
		table.setBackground(comparison.getBackground());
		addPersonalBestCell(table, "", MUTED_TEXT);
		addPersonalBestCell(table, "PB", PB_COLOR);
		addPersonalBestCell(table, "Average", MUTED_TEXT);
		addPersonalBestCell(table, "Time", MUTED_TEXT);
		addPersonalBestCell(
			table,
			personalBest.getFastestMillis() > 0L
				? formatDurationCompact(personalBest.getFastestMillis())
				: "-",
			PB_COLOR);
		addPersonalBestCell(
			table,
			formatDurationCompact(personalBest.getAverageElapsedMillis()),
			MUTED_TEXT);
		addPersonalBestCell(table, "Profit", MUTED_TEXT);
		addPersonalBestCell(table, formatSignedGpShort(personalBest.getBestProfit()), PB_COLOR);
		addPersonalBestCell(table, formatSignedGpShort(personalBest.getAverageProfit()), MUTED_TEXT);
		addPersonalBestCell(table, "XP", MUTED_TEXT);
		addPersonalBestCell(table, formatCompactCount(personalBest.getMostXp()), PB_COLOR);
		addPersonalBestCell(table, formatCompactCount(personalBest.getAverageXp()), MUTED_TEXT);
		comparison.add(table);

		card.add(Box.createVerticalStrut(5));
		card.add(comparison);
	}

	private void addPersonalBestCell(JPanel parent, String text, Color color)
	{
		JLabel label = new JLabel(text, SwingConstants.CENTER);
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setOpaque(true);
		label.setBackground(new Color(24, 24, 24));
		label.setBorder(BorderFactory.createEmptyBorder(2, 1, 2, 1));
		parent.add(label);
	}

	private void confirmClearTaskHistory()
	{
		int result = JOptionPane.showConfirmDialog(
			this,
			"Permanently clear every saved Slayer task?",
			"Clear Slayer Log",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);
		if (result == JOptionPane.YES_OPTION)
		{
			plugin.clearTaskHistory();
			renderedTaskHistorySize = -1;
			renderedTaskHistoryVisibleCount = -1;
			visibleTaskHistoryCount = TASK_LOG_PAGE_SIZE;
			refresh();
		}
	}

