			PvmToolsPlugin.getFourDosePotionId(ItemID.PRAYER_REGENERATION_POTION4));
		assertEquals(ItemID.PRAYER_REGENERATION_POTION4,
			PvmToolsPlugin.getFourDosePotionId(ItemID.PRAYER_REGENERATION_POTION3));
		assertEquals(ItemID.PRAYER_REGENERATION_POTION4,
