package com.arber.pvmtools;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class PvmTaskHistoryEntryTest
{
	@Test
	public void taskHistorySurvivesSerialization()
	{
		PvmTaskSnapshot task = new PvmTaskSnapshot(
			"Abyssal demons",
			"Catacombs of Kourend",
			0,
			186,
			1_700_000_000_000L,
			3_723_000L,
			1_850_000L,
			425_000L,
			118_500L,
			28_000L,
			17L,
			6L,
			820L,
			1_250L,
			480L,
			330L);
		PvmTaskHistoryEntry original = new PvmTaskHistoryEntry(task, 1_700_003_723_000L);

		PvmTaskHistoryEntry restored = PvmTaskHistoryEntry.deserialize(original.serialize());

		assertNotNull(restored);
		assertEquals(1_700_003_723_000L, restored.getFinishedMillis());
		assertEquals("Abyssal demons", restored.getTask().getName());
		assertEquals("Catacombs of Kourend", restored.getTask().getLocation());
		assertEquals(186, restored.getTask().getKilled());
		assertEquals(3_723_000L, restored.getTask().getElapsedMillis());
		assertEquals(1_850_000L, restored.getTask().getLootValue());
		assertEquals(425_000L, restored.getTask().getSupplyCostValue());
		assertEquals(1_425_000L, restored.getTask().getNetProfit());
		assertEquals(118_500L, restored.getTask().getCombatXp());
		assertEquals(28_000L, restored.getTask().getSlayerXp());
		assertEquals(17L, restored.getTask().getPotionDoseCount());
		assertEquals(6L, restored.getTask().getFoodCount());
		assertEquals(820L, restored.getTask().getCannonballCount());
		assertEquals(1_250L, restored.getTask().getRuneCount());
		assertEquals(480L, restored.getTask().getAmmoCount());
		assertEquals(330L, restored.getTask().getZulrahScaleCount());
	}

	@Test
	public void corruptHistoryEntryIsIgnored()
	{
		assertNull(PvmTaskHistoryEntry.deserialize("not-a-valid-entry"));
		assertNull(PvmTaskHistoryEntry.deserialize(""));
	}

	@Test
	public void legacyTaskHistoryLoadsWithEmptyCombatSupplyCounts()
	{
		PvmTaskHistoryEntry current = new PvmTaskHistoryEntry(
			new PvmTaskSnapshot(
				"Nechryael", "Slayer Tower", 0, 150, 1_000L, 50_000L,
				100_000L, 20_000L, 5_000L, 1_000L, 2L, 1L, 30L,
				12L, 4L, 6L),
			2_000L);
		String[] fields = current.serialize().split("\\|", -1);
		String legacy = String.join("|", Arrays.copyOf(fields, 13)) + "|" + fields[16];

		PvmTaskHistoryEntry restored = PvmTaskHistoryEntry.deserialize(legacy);

		assertNotNull(restored);
		assertEquals(0L, restored.getTask().getRuneCount());
		assertEquals(0L, restored.getTask().getAmmoCount());
		assertEquals(0L, restored.getTask().getZulrahScaleCount());
		assertEquals(2_000L, restored.getFinishedMillis());
	}

	@Test
	public void interruptedPartsOfTheSameTaskAreMerged()
	{
		PvmTaskHistoryEntry beforePause = new PvmTaskHistoryEntry(
			new PvmTaskSnapshot(
				"Dust devils", "Catacombs", 120, 200, 1_000L, 60_000L,
				500_000L, 100_000L, 20_000L, 5_000L, 2L, 1L, 100L),
			2_000L);
		PvmTaskHistoryEntry afterPause = new PvmTaskHistoryEntry(
			new PvmTaskSnapshot(
				"Dust devils", "Catacombs", 0, 200, 3_000L, 120_000L,
				700_000L, 150_000L, 30_000L, 10_000L, 3L, 2L, 200L),
			4_000L);

		assertEquals(true, beforePause.canMergeInterruptedTask(afterPause));
		PvmTaskHistoryEntry merged = beforePause.merge(afterPause);

		assertEquals(0, merged.getTask().getAmount());
		assertEquals(200, merged.getTask().getKilled());
		assertEquals(180_000L, merged.getTask().getElapsedMillis());
		assertEquals(1_200_000L, merged.getTask().getLootValue());
		assertEquals(250_000L, merged.getTask().getSupplyCostValue());
		assertEquals(50_000L, merged.getTask().getCombatXp());
		assertEquals(15_000L, merged.getTask().getSlayerXp());
		assertEquals(4_000L, merged.getFinishedMillis());
	}

	@Test
	public void twoCompletedAssignmentsAreNotMerged()
	{
		PvmTaskHistoryEntry first = new PvmTaskHistoryEntry(
			new PvmTaskSnapshot("Dust devils", "Catacombs", 0, 200, 1_000L, 1L, 1L, 0L, 0L, 0L, 0L, 0L, 0L),
			2_000L);
		PvmTaskHistoryEntry second = new PvmTaskHistoryEntry(
			new PvmTaskSnapshot("Dust devils", "Catacombs", 0, 200, 3_000L, 1L, 1L, 0L, 0L, 0L, 0L, 0L, 0L),
			4_000L);

		assertEquals(false, first.canMergeInterruptedTask(second));
	}
}

package com.arber.pvmtools;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PvmTaskPersonalBestTest
{
	@Test
	public void recordsAndAveragesAreCalculatedPerMonster()
	{
		PvmTaskHistoryEntry newest = entry(
			"Dust devils", 1_500_000L, 1_000_000L, 40_000L, 4_000L);
		PvmTaskHistoryEntry older = entry(
			"Dust devils", 1_800_000L, 900_000L, 50_000L, 3_000L);
		PvmTaskHistoryEntry oldest = entry(
			"Dust devils", 2_400_000L, 1_200_000L, 30_000L, 2_000L);
		PvmTaskHistoryEntry otherMonster = entry(
			"Abyssal demons", 3_000_000L, 2_000_000L, 60_000L, 1_000L);

		Map<String, PvmTaskPersonalBest> records = PvmTaskPersonalBest.index(
			Arrays.asList(newest, older, oldest, otherMonster));
		PvmTaskPersonalBest dustDevils = records.get("dust devils");

		assertEquals(2, records.size());
		assertEquals(3, dustDevils.getTaskCount());
		assertEquals(1_500_000L, dustDevils.getFastestMillis());
		assertEquals(1_200_000L, dustDevils.getBestProfit());
		assertEquals(50_000L, dustDevils.getMostXp());
		assertEquals(1_900_000L, dustDevils.getAverageElapsedMillis());
		assertEquals(1_033_333L, dustDevils.getAverageProfit());
		assertEquals(40_000L, dustDevils.getAverageXp());
		assertEquals(
			EnumSet.of(PvmTaskPersonalBest.Metric.TIME),
			dustDevils.getNewRecords(newest));
		assertEquals(
			EnumSet.of(PvmTaskPersonalBest.Metric.PROFIT),
			dustDevils.getCurrentRecords(oldest));
		assertEquals(
			EnumSet.of(PvmTaskPersonalBest.Metric.XP),
			dustDevils.getCurrentRecords(older));
		assertTrue(records.get("abyssal demons").isFirstRecord(otherMonster));
	}

	@Test
	public void equalResultDoesNotReplaceOrBreakPreviousRecord()
	{
		PvmTaskHistoryEntry newest = entry(
			"Nechryaels", 1_000_000L, 500_000L, 25_000L, 2_000L);
		PvmTaskHistoryEntry oldest = entry(
			"Nechryaels", 1_000_000L, 500_000L, 25_000L, 1_000L);

		PvmTaskPersonalBest records = PvmTaskPersonalBest.forTask(
			Arrays.asList(newest, oldest),
			"NECHRYAELS");

		assertTrue(records.getNewRecords(newest).isEmpty());
		assertTrue(records.getCurrentRecords(newest).isEmpty());
		assertEquals(
			EnumSet.allOf(PvmTaskPersonalBest.Metric.class),
			records.getCurrentRecords(oldest));
	}

	private PvmTaskHistoryEntry entry(
		String taskName,
		long elapsedMillis,
		long netProfit,
		long totalXp,
		long finishedMillis)
	{
		long supplyCost = 100_000L;
		PvmTaskSnapshot task = new PvmTaskSnapshot(
			taskName,
			"",
			0,
			200,
			1_000L,
			elapsedMillis,
			netProfit + supplyCost,
			supplyCost,
			totalXp,
			0L,
			0L,
			0L,
			0L);
		return new PvmTaskHistoryEntry(task, finishedMillis);
	}
}

